			"Superior dragon bones", "Hydra bones", "Drake bones", "Wyrm bones", "Wyrmling bones", "Frost dragon bones",
			"Ourg bones", "Fiendish ashes", "Vile ashes", "Malicious ashes", "Abyssal ashes", "Infernal ashes",
			"Ensouled dragon head", "Ensouled giant head");
		shelf(Family.MATERIALS,
			"Coal", "Iron ore", "Mithril ore", "Adamantite ore", "Runite ore", "Gold ore", "Silver ore", "Iron bar",
			"Steel bar", "Mithril bar", "Adamantite bar", "Runite bar", "Gold bar", "Silver bar", "Logs", "Oak logs",
			"Willow logs", "Teak logs", "Maple logs", "Mahogany logs", "Yew logs", "Magic logs", "Redwood logs", "Plank",
			"Oak plank", "Teak plank", "Mahogany plank", "Pure essence", "Daeyalt essence", "Feather", "Bucket of sand",
			"Soda ash", "Seaweed", "Giant seaweed", "Molten glass", "Flax", "Bow string", "Green dragonhide",
			"Blue dragonhide", "Red dragonhide", "Black dragonhide", "Green dragon leather", "Blue dragon leather",
			"Red dragon leather", "Black dragon leather", "Uncut sapphire", "Uncut emerald", "Uncut ruby", "Uncut diamond",
			"Uncut dragonstone", "Amethyst", "Steel nails", "Bolt of cloth", "Limestone brick", "Marble block", "Soft clay",
			"Air orb", "Unpowered orb", "Battlestaff");
		shelf(Family.CURRENCY,
			"Coins", "Tokkul", "Trading sticks", "Numulite");
		for (String name : new String[]{
			"Coal", "Iron ore", "Mithril ore", "Adamantite ore", "Runite ore", "Gold ore", "Silver ore", "Logs", "Oak logs",
			"Willow logs", "Teak logs", "Maple logs", "Mahogany logs", "Yew logs", "Magic logs", "Redwood logs", "Pure essence",
			"Daeyalt essence", "Feather", "Seaweed", "Giant seaweed", "Flax", "Green dragonhide", "Blue dragonhide",
			"Red dragonhide", "Black dragonhide", "Uncut sapphire", "Uncut emerald", "Uncut ruby", "Uncut diamond",
			"Uncut dragonstone", "Amethyst", "Chinchompa", "Red chinchompa", "Black chinchompa", "Snape grass",
			"Red spiders' eggs", "Limpwurt root", "White berries", "Potato cactus", "Mort myre fungus", "Bird nest",
			"Zulrah's scales", "Jangerberries", "Cave nightshade", "Poison ivy berries", "Cactus spine", "Blue dragon scale",
			"Yew roots", "Magic roots", "Amylase crystal", "Lava scale shard", "Nail beast nails", "Toad's legs",
			"Volcanic ash", "Ashes"})
		{
			GATHERED.add(key(name));
		}
	}

	private Catalogue()
	{
	}

	private static void shelf(Family family, String... names)
	{
		for (String name : names)
		{
			NAMES.put(key(name), name);
			SHELF.put(key(name), family);
		}
	}

	private static String key(String name)
	{
		return name.toLowerCase(Locale.ENGLISH).trim();
	}

	/** One item as a store sees it: which store, and how many of the store's units the item is. */
	public static final class Match
	{
		public final String store;
		public final Family family;
		public final int units;
		/** Whether this item is the one to picture the store by: a full potion, a clean herb. */
		public final boolean model;

		Match(String store, Family family, int units, boolean model)
		{
			this.store = store;
			this.family = family;
			this.units = units;
			this.model = model;
		}
	}

	/** The catalogue alone, with no picks of the player's own. */
	public static Catalogue.Lookup standard()
	{
		return new Lookup(Collections.emptySet(), Collections.emptySet());
	}

	/**
	 * The catalogue as one player has it: with items they asked to track added, and stores they
	 * never want to see taken out.
	 */
	public static Lookup with(String picked, String hidden)
	{
		return new Lookup(names(picked), names(hidden));
	}

	private static Set<String> names(String list)
	{
		Set<String> out = new HashSet<>();
		if (list == null)
		{
			return out;
		}
		for (String part : list.split("[,\\n]"))
		{
			String k = key(part);
			if (!k.isEmpty())
			{
				out.add(k);
			}
		}
		return out;
	}

	/** Finds the store an item belongs to. Immutable, so it can be shared between threads. */
	public static final class Lookup
	{
		private final Set<String> picked;
		private final Set<String> hidden;

		private Lookup(Set<String> picked, Set<String> hidden)
		{
			this.picked = picked;
			this.hidden = hidden;
		}

		/** @return the store the named item is filed under, or null when it is not one */
		public Match match(String itemName)
		{
			if (itemName == null)
			{
				return null;
			}
			String name = itemName.trim();
			if (name.isEmpty() || "null".equalsIgnoreCase(name))
			{
				return null;
			}
			Matcher dose = DOSE.matcher(name);
			if (dose.matches())
			{
				Match m = find(dose.group(1), Integer.parseInt(dose.group(2)), false);
				if (m != null && m.family == Family.POTIONS)
				{
					return new Match(m.store, m.family, m.units, m.units == 4);
				}
			}
			String k = key(name);
			if (k.startsWith(GRIMY))
			{
				Match m = find(k.substring(GRIMY.length()), 1, false);
				if (m != null && m.family == Family.HERBS)
				{
					return m;
				}
			}
			return find(name, 1, true);
		}

		private Match find(String name, int units, boolean model)
		{
			String k = key(name);
			if (hidden.contains(k))
			{
				return null;
			}
			Family family = SHELF.get(k);
			if (family != null)
			{
				return new Match(NAMES.get(k), family, units, model);
			}
			if (picked.contains(k))
			{
				// The player's own spelling may differ in case from the game's; the store takes the game's.
				return new Match(name.trim(), Family.PICKED, units, model);
			}
			return null;
		}

		/** The store a pack opens into, such as feathers from a feather pack, or null. */
		public String packOf(String itemName)
		{
			if (itemName == null)
			{
				return null;
			}
			String k = key(itemName);
			if (!k.endsWith(PACK))
			{
				return null;
			}
			Match m = match(itemName.trim().substring(0, itemName.trim().length() - PACK.length()));
			if (m == null)
			{
				// "Eye of newt pack" opens into eye of newt, but some packs are named for the plural.
				String singular = k.substring(0, k.length() - PACK.length());
				m = singular.endsWith("s") ? match(singular.substring(0, singular.length() - 1)) : null;
			}
			return m == null ? null : m.store;
		}
	}

	/** Whether a store is gathered (fished, mined, picked, chopped) rather than made from something else. */
	public static boolean gathered(String store)
	{
		return store != null && (GATHERED.contains(key(store)) || key(store).startsWith("raw ")
			|| SHELF.get(key(store)) == Family.HERBS || SHELF.get(key(store)) == Family.SEEDS
			|| SHELF.get(key(store)) == Family.PRAYER);
	}

	/** The shelf a store sits on, or the player's own shelf for one they picked. */
	public static Family family(String store)
	{
		Family f = store == null ? null : SHELF.get(key(store));
		return f == null ? Family.PICKED : f;
	}

	/** Every store in the catalogue, by its game name. */
	public static Set<String> all()
	{
		return Collections.unmodifiableSet(new HashSet<>(NAMES.values()));
	}

	/** Whether the store is money rather than supplies: it is never counted as self-made or run short. */
	public static boolean money(String store)
	{
		return family(store) == Family.CURRENCY;
	}
}

package com.codex.ironworks.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import net.runelite.api.Skill;

/**
 * Says where each change to what the player carries came from or went to, from what else happened
 * on the same tick: the experience gained, the menu option just clicked, a shop or trade window
 * being open, a death. Changes made at a bank or other storage are moves, not gains or losses, and
 * never reach here. Pure, so every rule can be tested without a client.
 */
public final class Classify
{
	static final Set<Skill> GATHERING = EnumSet.of(Skill.FISHING, Skill.MINING, Skill.WOODCUTTING, Skill.HUNTER,
		Skill.THIEVING, Skill.AGILITY, Skill.SAILING);
	static final Set<Skill> PRODUCTION = EnumSet.of(Skill.HERBLORE, Skill.COOKING, Skill.SMITHING, Skill.FLETCHING,
		Skill.CRAFTING, Skill.CONSTRUCTION, Skill.RUNECRAFT, Skill.FIREMAKING);
	static final Set<Skill> COMBAT = EnumSet.of(Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED,
		Skill.HITPOINTS, Skill.SLAYER);
	/** The containers a player carries that items go into and come out of unseen. */
	private static final Pattern CONTAINER = Pattern.compile(".*\\b(sack|bag|box|barrel|basket|pouch|kit|vessel)$");

	private Classify()
	{
	}

	/** A menu option the player clicked in the last couple of ticks. */
	public static final class Action
	{
		final String option;
		final String store;
		final boolean container;
		final boolean pack;

		/**
		 * @param option the option as shown, such as "Eat" or "Take"
		 * @param target the item or thing it was clicked on, colour tags and all
		 * @param store the store the clicked item belongs to, or null
		 * @param pack whether the clicked item is a pack bought from a shop
		 */
		public Action(String option, String target, String store, boolean pack)
		{
			this.option = option == null ? "" : option.toLowerCase(Locale.ENGLISH).trim();
			String plain = target == null ? "" : target.replaceAll("<[^>]*>", "").toLowerCase(Locale.ENGLISH).trim();
			this.store = store;
			this.container = CONTAINER.matcher(plain).matches();
			this.pack = pack;
		}

		boolean is(String... options)
		{
			for (String o : options)
			{
				if (option.equals(o) || option.startsWith(o + "-"))
				{
					return true;
				}
			}
			return false;
		}
	}

	/** Everything known about the tick the change happened on. */
	public static final class Context
	{
		boolean shop;
		boolean trade;
		boolean died;
		Set<Skill> xp = Collections.emptySet();
		List<Action> actions = Collections.emptyList();
		Map<Skill, Long> recent = Collections.emptyMap();

		public Context shop(boolean open)
		{
			shop = open;
			return this;
		}

		public Context trade(boolean open)
		{
			trade = open;
			return this;
		}

		public Context died(boolean value)
		{
			died = value;
			return this;
		}

		/** The skills that gained experience on this tick or the one before. */
		public Context xp(Set<Skill> skills)
		{
			xp = skills;
			return this;
		}

		public Context actions(List<Action> list)
		{
			actions = list;
			return this;
		}

		/** Experience gained per skill over the last quarter hour, to place items that arrive unseen. */
		public Context recent(Map<Skill, Long> xpBySkill)
		{
			recent = xpBySkill;
			return this;
		}
	}

	/**
	 * Files one tick's changes.
	 *
	 * @param delta units of each store gained (positive) or lost (negative) on the tick
	 * @param sacks units of each store the player has put into carried containers, drawn on as
	 *              they come out again and added to as they go in
	 */
	public static List<Flow> tick(Map<String, Long> delta, Context ctx, Map<String, Long> sacks)
	{
		List<Flow> out = new ArrayList<>();
		boolean anyGain = false;
		boolean anyLoss = false;
		for (Map.Entry<String, Long> e : delta.entrySet())
		{
			anyGain |= e.getValue() > 0 && !Catalogue.money(e.getKey());
			anyLoss |= e.getValue() < 0 && !Catalogue.money(e.getKey());
		}
		for (Map.Entry<String, Long> e : delta.entrySet())
		{
			long units = e.getValue();
			if (units > 0)
			{
				gain(e.getKey(), units, ctx, sacks, anyLoss, out);
			}
			else if (units < 0)
			{
				loss(e.getKey(), -units, ctx, sacks, anyGain, out);
			}
		}
		return out;
	}

	private static void gain(String store, long units, Context ctx, Map<String, Long> sacks, boolean anyLoss, List<Flow> out)
	{
		boolean money = Catalogue.money(store);
		if (ctx.shop)
		{
			out.add(Flow.in(store, units, money ? Source.SOLD : Source.BOUGHT, null));
			return;
		}
		if (ctx.trade)
		{
			out.add(Flow.in(store, units, Source.TRADED, null));
			return;
		}
		Action action = clicked(ctx, store);
		if (action != null && action.is("take"))
		{
			out.add(Flow.in(store, units, Source.LOOTED, null));
			return;
		}
		Action any = latest(ctx);
		if (any != null && any.pack && any.is("open"))
		{
			out.add(Flow.in(store, units, Source.BOUGHT, null));
			return;
		}
		if (any != null && any.container && any.is("empty", "withdraw", "take", "check", "remove"))
		{
			// Out of a carried container: what went in is not new, the rest arrived there unseen.
			long back = Math.min(units, sacks.getOrDefault(store, 0L));
			if (back > 0)
			{
				put(sacks, store, -back);
			}
			if (units > back)
			{
				out.add(arrival(store, units - back, ctx.recent));
			}
			return;
		}
		if (money && ctx.xp.contains(Skill.MAGIC))
		{
			out.add(Flow.in(store, units, Source.ALCHED, null));
			return;
		}
		Skill skill = gainSkill(store, ctx.xp);
		if (skill != null)
		{
			Source source = skill == Skill.FARMING ? Source.FARMED
				: PRODUCTION.contains(skill) || skill == Skill.MAGIC ? Source.MADE
				: GATHERING.contains(skill) ? Source.GATHERED : Source.LOOTED;
			out.add(Flow.in(store, units, source, source == Source.LOOTED ? null : skill.getName()));
			return;
		}
		if (any != null && any.is("open", "search", "loot", "claim", "collect", "take-all"))
		{
			out.add(Flow.in(store, units, Source.REWARD, null));
			return;
		}
		out.add(Flow.in(store, units, Source.OTHER, null));
	}

	/** The skill a gain is put down to: farming first, then making or gathering as the item is. */
	private static Skill gainSkill(String store, Set<Skill> xp)
	{
		if (xp.isEmpty())
		{
			return null;
		}
		if (xp.contains(Skill.FARMING))
		{
			return Skill.FARMING;
		}
		Skill made = first(xp, PRODUCTION);
		Skill gathered = first(xp, GATHERING);
		if (made != null && gathered != null)
		{
			return Catalogue.gathered(store) ? gathered : made;
		}
		if (made != null)
		{
			return made;
		}
		if (gathered != null)
		{
			return gathered;
		}
		if (xp.contains(Skill.MAGIC) && first(xp, COMBAT) == null)
		{
			// Enchanting bolts, making planks: magic alone, no combat beside it.
			return Skill.MAGIC;
		}
		return first(xp, COMBAT);
	}

	private static void loss(String store, long units, Context ctx, Map<String, Long> sacks, boolean anyGain, List<Flow> out)
	{
		Family family = Catalogue.family(store);
		if (ctx.died)
		{
			out.add(Flow.out(store, units, Use.DIED, null));
			return;
		}
		if (ctx.shop)
		{
			out.add(Flow.out(store, units, family == Family.CURRENCY && anyGain ? Use.SPENT : Use.SOLD, null));
			return;
		}
		if (ctx.trade)
		{
			out.add(Flow.out(store, units, Use.TRADED, null));
			return;
		}
		Action action = clicked(ctx, store);
		if (action != null)
		{
			if (action.is("eat", "drink", "quaff", "sip"))
			{
				out.add(Flow.out(store, units, Use.CONSUMED, null));
				return;
			}
			if (action.is("drop", "destroy", "release"))
			{
				out.add(Flow.out(store, units, Use.DROPPED, null));
				return;
			}
			if (action.is("bury", "scatter"))
			{
				out.add(Flow.out(store, units, Use.OFFERED, Skill.PRAYER.getName()));
				return;
			}
		}
		Action any = latest(ctx);
		if (any != null && any.container && any.is("fill", "use", "store", "deposit", "add"))
		{
			put(sacks, store, units);
			return;
		}
		Set<Skill> xp = ctx.xp;
		if (xp.contains(Skill.PRAYER))
		{
			out.add(Flow.out(store, units, Use.OFFERED, Skill.PRAYER.getName()));
			return;
		}
		if (xp.contains(Skill.FARMING))
		{
			out.add(Flow.out(store, units, Use.PLANTED, Skill.FARMING.getName()));
			return;
		}
		if (family == Family.RUNES && (xp.contains(Skill.MAGIC) || first(xp, COMBAT) != null))
		{
			out.add(Flow.out(store, units, Use.CAST, null));
			return;
		}
		if (family == Family.AMMO && xp.contains(Skill.RANGED))
		{
			out.add(Flow.out(store, units, Use.FIRED, null));
			return;
		}
		Skill made = first(xp, PRODUCTION);
		if (made == null && xp.contains(Skill.MAGIC))
		{
			made = Skill.MAGIC;
		}
		if (made != null)
		{
			out.add(Flow.out(store, units, Use.MADE_INTO, made.getName()));
			return;
		}
		if (family == Family.RUNES)
		{
			// Teleports and spells that give no experience still use runes.
			out.add(Flow.out(store, units, Use.CAST, null));
			return;
		}
		if (family == Family.AMMO)
		{
			// A shot that misses gives no experience but is spent all the same.
			out.add(Flow.out(store, units, Use.FIRED, null));
			return;
		}
		out.add(Flow.out(store, units, Use.USED, null));
	}

	/**
	 * Something that turned up without being seen arrive, such as fish emptied from a barrel or
	 * herbs from a herb sack: put down to what the player has been doing lately.
	 */
	public static Flow arrival(String store, long units, Map<Skill, Long> recent)
	{
		Skill farming = recent.getOrDefault(Skill.FARMING, 0L) > 0 ? Skill.FARMING : null;
		Skill gathered = top(recent, GATHERING);
		Skill made = top(recent, PRODUCTION);
		Skill fought = top(recent, COMBAT);
		if (Catalogue.gathered(store))
		{
			if (gathered != null && (farming == null || recent.get(gathered) >= recent.get(Skill.FARMING)))
			{
				return Flow.in(store, units, Source.GATHERED, gathered.getName());
			}
			if (farming != null)
			{
				return Flow.in(store, units, Source.FARMED, farming.getName());
			}
		}
		else if (made != null)
		{
			return Flow.in(store, units, Source.MADE, made.getName());
		}
		if (fought != null)
		{
			return Flow.in(store, units, Source.LOOTED, null);
		}
		return Flow.in(store, units, Source.OTHER, null);
	}

	private static Action clicked(Context ctx, String store)
	{
		for (int i = ctx.actions.size() - 1; i >= 0; i--)
		{
			Action a = ctx.actions.get(i);
			if (store.equals(a.store))
			{
				return a;
			}
		}
		return null;
	}

	private static Action latest(Context ctx)
	{
		return ctx.actions.isEmpty() ? null : ctx.actions.get(ctx.actions.size() - 1);
	}

	private static Skill first(Set<Skill> xp, Set<Skill> kind)
	{
		for (Skill s : xp)
		{
			if (kind.contains(s))
			{
				return s;
			}
		}
		return null;
	}

	private static Skill top(Map<Skill, Long> recent, Set<Skill> kind)
	{
		Skill best = null;
		long most = 0;
		for (Map.Entry<Skill, Long> e : recent.entrySet())
		{
			if (kind.contains(e.getKey()) && e.getValue() > most)
			{
				most = e.getValue();
				best = e.getKey();
			}
		}
		return best;
	}

	private static void put(Map<String, Long> map, String key, long add)
	{
		long v = map.getOrDefault(key, 0L) + add;
		if (v <= 0)
		{
			map.remove(key);
		}
		else
		{
			map.put(key, v);
		}
	}
}

package com.codex.ironworks.core;

import java.util.HashMap;
import java.util.Map;

/** One calendar day: how long was played and what each store did. */
public final class Day
{
	/** Milliseconds logged in. */
	long played;
	Map<String, Tally> stores = new HashMap<>();

	public long getPlayed()
	{
		return played;
	}

	Tally tally(String store)
	{
		return stores.computeIfAbsent(store, k -> new Tally());
	}

	Day repair()
	{
		played = Math.max(0, played);
		Map<String, Tally> clean = new HashMap<>();
		if (stores != null)
		{
			stores.forEach((k, t) ->
			{
				if (k != null && t != null && !t.repair().isEmpty())
				{
					clean.put(k, t);
				}
			});
		}
		stores = clean;
		return this;
	}
}

package com.codex.ironworks.core;

import java.util.HashMap;
import java.util.Map;

/**
 * What the player lost on their last death and has not taken back. It lies at the grave for
 * fifteen minutes of play, then waits at Death's Office until reclaimed. Dying again before then
 * loses it for good.
 */
public final class Death
{
	/** Play time a grave lasts before its items move to Death's Office. */
	public static final long GRAVE_MS = 15 * 60_000L;

	long at;
	/** Play time on the account's clock when the player died. */
	long playedAt;
	int world;
	/** Items lost and not yet seen come back, by item id. */
	Map<Integer, Long> items = new HashMap<>();
	/** How many items were lost in all, to tell how much has come back. */
	long lost;

	Death()
	{
	}

	Death(Map<Integer, Long> items, long at, long playedAt, int world)
	{
		this.at = at;
		this.playedAt = playedAt;
		this.world = world;
		items.forEach((k, v) ->
		{
			if (k != null && v != null && v > 0)
			{
				this.items.put(k, v);
				lost += v;
			}
		});
	}

	/** Play time left at the grave, or 0 once the items have gone to Death's Office. */
	public long graveLeft(long played)
	{
		return Math.max(0, GRAVE_MS - (played - playedAt));
	}

	public long getAt()
	{
		return at;
	}

	public int getWorld()
	{
		return world;
	}

	public Map<Integer, Long> getItems()
	{
		return items;
	}

	public long getLost()
	{
		return lost;
	}

	/** Items seen come back; true when so little is left that the death is settled. */
	boolean back(int item, long qty)
	{
		Long held = items.get(item);
		if (held != null && qty > 0)
		{
			if (qty >= held)
			{
				items.remove(item);
			}
			else
			{
				items.put(item, held - qty);
			}
		}
		long left = 0;
		for (long v : items.values())
		{
			left += v;
		}
		return items.isEmpty() || left * 10 < lost;
	}

	Death repair()
	{
		Map<Integer, Long> clean = new HashMap<>();
		if (items != null)
		{
			items.forEach((k, v) ->
			{
				if (k != null && v != null && v > 0)
				{
					clean.put(k, v);
				}
			});
		}
		items = clean;
		lost = Math.max(lost, 0);
		return this;
	}
}

