package com.codex.ironworks.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * A shop run: shop visits close enough together to be one trip, whether going round several shops
 * or hopping worlds at one.
 */
public final class Run
{
	/** Visits further apart than this start a new run. */
	public static final long GAP = 10 * 60_000L;

	long start;
	long end;
	/** The shops visited, by key, in the order first visited. */
	List<String> shops = new ArrayList<>();
	/** Items bought, by item name. */
	Map<String, Long> bought = new HashMap<>();
	/** Coins and tokens paid, by the currency's store. */
	Map<String, Long> spent = new HashMap<>();
	Set<Integer> worlds = new HashSet<>();
	int visits;

	Run()
	{
	}

	Run(long now)
	{
		start = now;
		end = now;
	}

	public long getStart()
	{
		return start;
	}

	public long getEnd()
	{
		return end;
	}

	public long duration()
	{
		return Math.max(0, end - start);
	}

	public List<String> getShops()
	{
		return shops;
	}

	public Map<String, Long> getBought()
	{
		return bought;
	}

	public Map<String, Long> getSpent()
	{
		return spent;
	}

	public int worlds()
	{
		return worlds.size();
	}

	public int getVisits()
	{
		return visits;
	}

	public long items()
	{
		long sum = 0;
		for (long v : bought.values())
		{
			sum += v;
		}
		return sum;
	}

	Run repair()
	{
		shops = shops == null ? new ArrayList<>() : shops;
		shops.removeIf(s -> s == null);
		bought = bought == null ? new HashMap<>() : bought;
		bought.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || e.getValue() <= 0);
		spent = spent == null ? new HashMap<>() : spent;
		spent.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || e.getValue() <= 0);
		worlds = worlds == null ? new HashSet<>() : worlds;
		worlds.removeIf(w -> w == null);
		end = Math.max(start, end);
		return this;
	}
}

package com.codex.ironworks.core;

/**
 * How long one store lasts at the pace the player actually works through it, measured per hour
 * played rather than per day, so a week away does not make the stores look endless.
 */
public final class Runway
{
	/** Play needed before a pace is trusted. */
	public static final long LEARN_MS = 60 * 60_000L;

	public enum Status
	{
		/** None left, and it is being used. */
		OUT,
		/** Runs out within the warning time. */
		LOW,
		/** Short of the runway the player wants. */
		SHORT,
		/** Lasts at least the wanted runway. */
		OK,
		/** Coming in at least as fast as it goes. */
		STEADY,
		/** Not used lately. */
		IDLE,
		/** Not enough play yet to tell. */
		LEARNING
	}

	public final String store;
	public final long stock;
	/** Units used per hour played, or 0. */
	public final double burn;
	/** Units gained per hour played, or 0. */
	public final double gain;
	/** Hours of play the stock lasts at the burn alone; infinite when nothing is used. */
	public final double hours;
	/** Units to add to reach the wanted runway. */
	public final long need;
	public final Status status;

	private Runway(String store, long stock, double burn, double gain, double hours, long need, Status status)
	{
		this.store = store;
		this.stock = stock;
		this.burn = burn;
		this.gain = gain;
		this.hours = hours;
		this.need = need;
		this.status = status;
	}

	/**
	 * @param recent the last week or so, to measure the pace from
	 * @param target hours of play the player wants each store to last
	 * @param warn hours of play under which a store is running low
	 */
	public static Runway of(String store, long stock, Window recent, double target, double warn)
	{
		Tally t = recent.tally(store);
		if (recent.played < LEARN_MS)
		{
			return new Runway(store, stock, 0, 0, Double.POSITIVE_INFINITY, 0, Status.LEARNING);
		}
		double h = recent.played / 3_600_000.0;
		double burn = t.burned() / h;
		double gain = t.gained() / h;
		if (burn <= 0)
		{
			return new Runway(store, stock, 0, gain, Double.POSITIVE_INFINITY, 0, Status.IDLE);
		}
		double hours = stock / burn;
		long need = (long) Math.max(0, Math.ceil(target * burn - stock));
		Status status;
		if (stock <= 0)
		{
			status = Status.OUT;
		}
		else if (gain >= burn && !Catalogue.money(store))
		{
			status = Status.STEADY;
		}
		else if (hours < warn)
		{
			status = Status.LOW;
		}
		else if (hours < target)
		{
			status = Status.SHORT;
		}
		else
		{
			status = Status.OK;
		}
		return new Runway(store, stock, burn, gain, hours, need, status);
	}

	/** Whether the store wants topping up: out, low or short of the wanted runway. */
	public boolean wanting()
	{
		return status == Status.OUT || status == Status.LOW || status == Status.SHORT;
	}
}

package com.codex.ironworks.core;

/**
 * Counts the game ticks after a login or a world hop until the account can be read. The game
 * says the player is logged in before it has sent their levels and varbits, which arrive over the
 * first ticks; read too soon, every skill is level 1 and no account is an ironman. RuneLite's own
 * experience tracker waits two ticks the same way.
 */
public final class Settle
{
	/** Ticks after logging in before levels and varbits are trusted. */
	static final int TICKS = 2;

	private int wait = TICKS;

	/** Logging in or hopping: the account is not to be read until it has settled. */
	public void restart()
	{
		wait = TICKS;
	}

	/**
	 * A game tick passed while logged in.
	 *
	 * @return true on the one tick the account settles, when it should be read afresh
	 */
	public boolean tick()
	{
		if (wait <= 0)
		{
			return false;
		}
		wait--;
		return wait == 0;
	}

	/** Whether levels and varbits read now are the account's own. */
	public boolean isSettled()
	{
		return wait <= 0;
	}
}

package com.codex.ironworks.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * The whole bank as Codex Bank Steward last saw it, which it publishes for the other Codex
 * plugins under {@link #KEY} of its config group:
 * {@code {"version":1,"savedAt":ms,"items":{"id":qty},"truncated":false}}, item ids canonical,
 * potion storage and the inventory left out. Read only, and only taken when it is newer than
 * the bank the Provisioner saw itself, such as on the first login after installing.
 */
public final class SharedBank
{
	public static final String GROUP = "codexbanksteward";
	public static final String KEY = "bankV1";

	private final long savedAt;
	private final Map<Integer, Long> items;

	private SharedBank(long savedAt, Map<Integer, Long> items)
	{
		this.savedAt = savedAt;
		this.items = items;
	}

	/** Reads a published snapshot; null when there is none or it cannot be read. */
	public static SharedBank read(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			if (root == null || !root.isJsonObject())
			{
				return null;
			}
			JsonObject o = root.getAsJsonObject();
			JsonElement at = o.get("savedAt");
			JsonElement list = o.get("items");
			Long savedAt = Json.whole(at);
			if (savedAt == null || list == null || !list.isJsonObject())
			{
				return null;
			}
			Map<Integer, Long> items = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : list.getAsJsonObject().entrySet())
			{
				try
				{
					int id = Integer.parseInt(e.getKey());
					Long qty = Json.whole(e.getValue());
					if (id > 0 && qty != null && qty > 0)
					{
						// No stack holds more than an int; a bigger figure is damage, not items.
						items.put(id, Json.count(qty));
					}
				}
				catch (NumberFormatException ignored)
				{
					// One unreadable entry does not spoil the rest.
				}
			}
			return savedAt > 0 ? new SharedBank(savedAt, items) : null;
		}
		catch (JsonParseException | IllegalStateException | NumberFormatException e)
		{
			return null;
		}
	}

	public long getSavedAt()
	{
		return savedAt;
	}

	public Map<Integer, Long> getItems()
	{
		return Collections.unmodifiableMap(items);
	}
}

package com.codex.ironworks.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** A shop the player has used, told apart from a namesake elsewhere by the map square it stands in. */
public final class Shop
{
	String name;
	int region;
	long first;
	long last;
	int visits;
	/** What it sells, by item id. */
	Map<String, Ware> wares = new HashMap<>();

	Shop()
	{
	}

	Shop(String name, int region, long now)
	{
		this.name = name;
		this.region = region;
		this.first = now;
		this.last = now;
	}

	public String key()
	{
		return key(name, region);
	}

	static String key(String name, int region)
	{
		return name + "@" + region;
	}

	Ware ware(int item, String itemName)
	{
		Ware w = wares.computeIfAbsent(String.valueOf(item), k -> new Ware(item, itemName));
		if (itemName != null)
		{
			w.name = itemName;
		}
		return w;
	}

	public Ware getWare(int item)
	{
		return wares.get(String.valueOf(item));
	}

	/** What the shop sells, most bought first, then by name. */
	public List<Ware> getWares()
	{
		List<Ware> list = new ArrayList<>(wares.values());
		list.sort((a, b) -> a.bought != b.bought ? Long.compare(b.bought, a.bought)
			: String.valueOf(a.name).compareToIgnoreCase(String.valueOf(b.name)));
		return list;
	}

	public String getName()
	{
		return name;
	}

	public int getRegion()
	{
		return region;
	}

	public long getFirst()
	{
		return first;
	}

	public long getLast()
	{
		return last;
	}

	public int getVisits()
	{
		return visits;
	}

	/** Everything paid here, by currency. */
	public Map<String, Long> spent()
	{
		Map<String, Long> sum = new HashMap<>();
		wares.values().forEach(w -> w.spent.forEach((k, v) -> sum.merge(k, v, Long::sum)));
		return sum;
	}

	public long bought()
	{
		long sum = 0;
		for (Ware w : wares.values())
		{
			sum += w.bought;
		}
		return sum;
	}

	Shop repair()
	{
		name = name == null || name.trim().isEmpty() ? "Shop" : name;
		visits = Math.max(0, visits);
		Map<String, Ware> clean = new HashMap<>();
		if (wares != null)
		{
			wares.forEach((k, w) ->
			{
				if (k != null && w != null)
				{
					clean.put(k, w.repair());
				}
			});
		}
		wares = clean;
		return this;
	}
}

