import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.ToDoubleFunction;

/**
 * Where a stretch of play's supplies came from and went, weighed by worth so a hundred feathers
 * do not outweigh one shark-sized stack of runes. Money itself is left out: coins are what supplies
 * are bought with, not a supply.
 */
public final class Summary
{
	/** One store's part in a source or use. */
	public static final class Line
	{
		public final String store;
		public final long units;
		public final double worth;

		Line(String store, long units, double worth)
		{
			this.store = store;
			this.units = units;
			this.worth = worth;
		}
	}

	public final Map<Source, Double> sources = new EnumMap<>(Source.class);
	public final Map<Use, Double> uses = new EnumMap<>(Use.class);
	public final Map<Source, List<Line>> bySource = new EnumMap<>(Source.class);
	public final Map<Use, List<Line>> byUse = new EnumMap<>(Use.class);
	/** Worth gathered, made or farmed with each skill. */
	public final Map<String, Double> skills = new HashMap<>();
	public final double gained;
	public final double used;
	/** Share of what came in that the player made or gathered themselves, by worth; -1 when nothing came in. */
	public final double self;
	public final long played;

	private Summary(Window w, ToDoubleFunction<String> unitWorth)
	{
		double in = 0;
		double out = 0;
		double own = 0;
		for (Map.Entry<String, Tally> e : w.stores.entrySet())
		{
			String store = e.getKey();
			if (Catalogue.money(store))
			{
				continue;
			}
			// Untradeable things are worth nothing on the exchange but are still supplies; count them a coin each.
			double each = Math.max(1, unitWorth.applyAsDouble(store));
			Tally t = e.getValue();
			for (Source s : Source.values())
			{
				long units = t.in(s);
				if (units > 0)
				{
					double worth = units * each;
					sources.merge(s, worth, Double::sum);
					bySource.computeIfAbsent(s, k -> new ArrayList<>()).add(new Line(store, units, worth));
					in += worth;
					own += s.isSelf() ? worth : 0;
				}
			}
			for (Use u : Use.values())
			{
				long units = t.out(u);
				if (units > 0)
				{
					double worth = units * each;
					uses.merge(u, worth, Double::sum);
					byUse.computeIfAbsent(u, k -> new ArrayList<>()).add(new Line(store, units, worth));
					out += worth;
				}
			}
			long selfUnits = t.self();
			if (selfUnits > 0)
			{
				t.skills.forEach((skill, units) -> skills.merge(skill, units * each, Double::sum));
			}
		}
		bySource.values().forEach(l -> l.sort((a, b) -> Double.compare(b.worth, a.worth)));
		byUse.values().forEach(l -> l.sort((a, b) -> Double.compare(b.worth, a.worth)));
		gained = in;
		used = out;
		self = in > 0 ? own / in : -1;
		played = w.played;
	}

	/**
	 * @param unitWorth what one unit of a store is worth, such as one dose of a potion
	 */
	public static Summary of(Window window, ToDoubleFunction<String> unitWorth)
	{
		return new Summary(window, unitWorth);
	}
}

package com.codex.ironworks.core;

import java.util.HashMap;
import java.util.Map;

/** Units of one store in and out, by where they came from and went to. */
public final class Tally
{
	/** Units gained, by {@link Source} name. */
	Map<String, Long> in = new HashMap<>();
	/** Units lost, by {@link Use} name. */
	Map<String, Long> out = new HashMap<>();
	/** Units gathered, made or farmed, by the skill's name. */
	Map<String, Long> skills = new HashMap<>();

	void add(Flow f)
	{
		if (f.isGain())
		{
			in.merge(f.source.name(), f.units, Long::sum);
			if (f.skill != null)
			{
				skills.merge(f.skill, f.units, Long::sum);
			}
		}
		else
		{
			out.merge(f.use.name(), f.units, Long::sum);
		}
	}

	void add(Tally t)
	{
		t.in.forEach((k, v) -> in.merge(k, v, Long::sum));
		t.out.forEach((k, v) -> out.merge(k, v, Long::sum));
		t.skills.forEach((k, v) -> skills.merge(k, v, Long::sum));
	}

	public long in(Source source)
	{
		return in.getOrDefault(source.name(), 0L);
	}

	public long out(Use use)
	{
		return out.getOrDefault(use.name(), 0L);
	}

	/** Everything gained, from any source this version knows. */
	public long gained()
	{
		long sum = 0;
		for (Source s : Source.values())
		{
			sum += in(s);
		}
		return sum;
	}

	/** What was worked through: eaten, cast, fired, made into something else and so on. */
	public long burned()
	{
		long sum = 0;
		for (Use u : Use.values())
		{
			if (u.isBurn())
			{
				sum += out(u);
			}
		}
		return sum;
	}

	/** What the player gathered, made or farmed themselves. */
	public long self()
	{
		long sum = 0;
		for (Source s : Source.values())
		{
			if (s.isSelf())
			{
				sum += in(s);
			}
		}
		return sum;
	}

	public Map<String, Long> getSkills()
	{
		return skills;
	}

	boolean isEmpty()
	{
		return in.isEmpty() && out.isEmpty();
	}

	/** Drops figures that are not counts, from a damaged save. */
	Tally repair()
	{
		in = clean(in);
		out = clean(out);
		skills = clean(skills);
		return this;
	}

	private static Map<String, Long> clean(Map<String, Long> m)
	{
		Map<String, Long> c = new HashMap<>();
		if (m != null)
		{
			m.forEach((k, v) ->
			{
				if (k != null && v != null && v > 0)
				{
					c.put(k, v);
				}
			});
		}
		return c;
	}
}

package com.codex.ironworks.core;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Turns what the player carries, tick by tick, into gains and losses, and keeps moves out of them.
 * Anything moved at a bank, a deposit box or another storage is a move, not a gain or a loss. A
 * bank visit is checked whole instead: whatever the bank side holds beyond what went in and came
 * out arrived unseen, such as herbs emptied from a herb sack or fish from a barrel, and is put down
 * to what the player had been doing. Items lost on death wait in a grave until picked up again.
 */
public final class Tracker
{
	/** Ticks after the bank opens before its items and potion storage are all in. */
	static final int OPEN_TICKS = 3;
	/** Ticks after a storage closes in which a last move may still arrive. */
	static final int CLOSE_TICKS = 2;
	/** Ticks a death holds what was lost; uncollected after this, it is gone. */
	static final int GRAVE_TICKS = 6000;

	private final Works works;

	private Map<String, Long> carried;
	private boolean bank;
	private int bankWait;
	private int bankClose;
	private Map<String, Long> carriedAtOpen;
	private Map<String, Long> openTotal;
	/** The bank side as the player left it, with what a deposit box added since; null when not watched this session. */
	private Map<String, Long> expectedBank;
	private int storage;
	private int storageGrace;
	private boolean deposit;
	private final Map<String, Long> grave = new HashMap<>();
	private int graveTicks;

	public Tracker(Works works)
	{
		this.works = works;
	}

	/**
	 * Logging in, or the plugin starting: what is carried is taken as it is, and the bank is not
	 * compared with how it was left, since the account may have been played elsewhere.
	 */
	public void restart(LocalDate day)
	{
		carried = null;
		bank = false;
		bankWait = 0;
		bankClose = 0;
		carriedAtOpen = null;
		openTotal = null;
		expectedBank = null;
		storage = 0;
		storageGrace = 0;
		deposit = false;
		buryGrave(day);
	}

	/** A world hop: nothing changes hands, but every window shuts and the next carried reading starts afresh. */
	public void hop()
	{
		carried = null;
		bank = false;
		bankWait = 0;
		bankClose = 0;
		openTotal = null;
		storage = 0;
		storageGrace = 0;
		deposit = false;
	}

	public void bankOpened()
	{
		if (bank)
		{
			return;
		}
		bank = true;
		bankWait = OPEN_TICKS;
		bankClose = 0;
		carriedAtOpen = carried == null ? null : new HashMap<>(carried);
	}

	public void bankClosed()
	{
		if (!bank)
		{
			return;
		}
		bank = false;
		bankClose = CLOSE_TICKS;
	}

	/** A deposit box, seed vault, group storage or other store opened. */
	public void storageOpened(boolean depositBox)
	{
		storage++;
		deposit |= depositBox;
	}

	public void storageClosed()
	{
		storage = Math.max(0, storage - 1);
		storageGrace = CLOSE_TICKS;
		if (storage == 0)
		{
			deposit = false;
		}
	}

	public boolean isBankOpen()
	{
		return bank;
	}

	/** Whether moves are being made now, so changes to what is carried are not gains or losses. */
	public boolean moving()
	{
		return bank || bankWait > 0 || bankClose > 0 || storage > 0 || storageGrace > 0;
	}

	/**
	 * One game tick.
	 *
	 * @param now what is carried now, in store units
	 * @return the gains and losses recorded on this tick
	 */
	public List<Flow> tick(Map<String, Long> now, Classify.Context ctx, LocalDate day, long time)
	{
		List<Flow> flows = new ArrayList<>();
		works.place(Place.CARRIED, now, time);
		if (carried != null)
		{
			Map<String, Long> delta = delta(carried, now);
			if (!delta.isEmpty())
			{
				if (moving())
				{
					if (deposit && expectedBank != null)
					{
						delta.forEach((k, v) ->
						{
							if (v < 0)
							{
								expectedBank.merge(k, -v, Long::sum);
							}
						});
					}
				}
				else
				{
					flows.addAll(settle(Classify.tick(delta, ctx, works.sacks), ctx));
				}
			}
		}
		carried = new HashMap<>(now);

		if (bank && bankWait > 0 && --bankWait == 0)
		{
			flows.addAll(opened(ctx));
		}
		if (bankClose > 0 && --bankClose == 0)
		{
			flows.addAll(closed(ctx));
		}
		if (storageGrace > 0 && storage == 0)
		{
			storageGrace--;
		}
		if (graveTicks > 0 && --graveTicks == 0)
		{
			buryGrave(day);
		}
		works.record(flows, day);
		return flows;
	}

	/** The bank's items are all in: what arrived there unseen since the last visit is counted. */
	private List<Flow> opened(Classify.Context ctx)
	{
		openTotal = works.stocks();
		List<Flow> flows = new ArrayList<>();
		if (expectedBank == null || carriedAtOpen == null)
		{
			return flows;
		}
		Map<String, Long> was = new HashMap<>(expectedBank);
		carriedAtOpen.forEach((k, v) -> was.merge(k, v, Long::sum));
		Map<String, Long> is = bankSide();
		carried.forEach((k, v) -> is.merge(k, v, Long::sum));
		delta(was, is).forEach((store, units) ->
		{
			if (units > 0)
			{
				flows.addAll(arrive(store, units, ctx));
			}
		});
		return flows;
	}

	/**
	 * The visit is over: anything that came into the bank side and the pack together, beyond what
	 * was there at the start, came out of a carried container; anything gone went into one, or was
	 * eaten or drunk at the bank.
	 */
	private List<Flow> closed(Classify.Context ctx)
	{
		List<Flow> flows = new ArrayList<>();
		if (openTotal != null)
		{
			delta(openTotal, works.stocks()).forEach((store, units) ->
			{
				if (units > 0)
				{
					flows.addAll(arrive(store, units, ctx));
				}
				else
				{
					Family f = Catalogue.family(store);
					if (f == Family.FOOD && !store.startsWith("Raw ") || f == Family.POTIONS)
					{
						flows.add(Flow.out(store, -units, Use.CONSUMED, null));
					}
					else if (Catalogue.gathered(store) || f == Family.MATERIALS || f == Family.SEEDS)
					{
						works.sacks.merge(store, -units, Long::sum);
					}
				}
			});
		}
		openTotal = null;
		expectedBank = bankSide();
		return flows;
	}

	/** Units that turned up unseen: first what went into a container, then new arrivals. */
	private List<Flow> arrive(String store, long units, Classify.Context ctx)
	{
		long back = Math.min(units, works.sacks.getOrDefault(store, 0L));
		if (back > 0)
		{
			long left = works.sacks.get(store) - back;
			if (left > 0)
			{
				works.sacks.put(store, left);
			}
			else
			{
				works.sacks.remove(store);
			}
		}
		if (units > back)
		{
			return settle(Collections.singletonList(Classify.arrival(store, units - back, ctx.recent)), ctx);
		}
		return Collections.emptyList();
	}

	/** Losses on death go to the grave; gains of what is in it are the player taking it back. */
	private List<Flow> settle(List<Flow> flows, Classify.Context ctx)
	{
		List<Flow> out = new ArrayList<>();
		for (Flow f : flows)
		{
			if (!f.isGain() && f.use == Use.DIED)
			{
				grave.merge(f.store, f.units, Long::sum);
				graveTicks = GRAVE_TICKS;
				continue;
			}
			long held = f.isGain() ? grave.getOrDefault(f.store, 0L) : 0;
			if (held > 0 && f.source != Source.GATHERED && f.source != Source.MADE && f.source != Source.FARMED
				&& f.source != Source.BOUGHT)
			{
				long back = Math.min(held, f.units);
				if (held - back > 0)
				{
					grave.put(f.store, held - back);
				}
				else
				{
					grave.remove(f.store);
				}
				if (f.units > back)
				{
					out.add(Flow.in(f.store, f.units - back, f.source, f.skill));
				}
				continue;
			}
			out.add(f);
		}
		return out;
	}

	/** What was never taken back from a grave is gone. */
	private void buryGrave(LocalDate day)
	{
		if (grave.isEmpty())
		{
			return;
		}
		List<Flow> lost = new ArrayList<>();
		grave.forEach((k, v) -> lost.add(Flow.out(k, v, Use.DIED, null)));
		grave.clear();
		graveTicks = 0;
		works.record(lost, day);
	}

	private Map<String, Long> bankSide()
	{
		Map<String, Long> side = new HashMap<>(works.place(Place.BANK));
		works.place(Place.POTION_STORAGE).forEach((k, v) -> side.merge(k, v, Long::sum));
		return side;
	}

	static Map<String, Long> delta(Map<String, Long> was, Map<String, Long> is)
	{
		Map<String, Long> d = new HashMap<>();
		is.forEach((k, v) -> d.merge(k, v, Long::sum));
		was.forEach((k, v) -> d.merge(k, -v, Long::sum));
		d.values().removeIf(v -> v == 0);
		return d;
	}
}

package com.codex.ironworks.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.Map;

/**
 * Tells whether a save holds anything its read-back lacks: a field or an entry of a kind a later
 * version keeps, or something damage put in that reading had to leave out. Such a save reads
 * without an error, but the next save would quietly drop what this version did not understand,
 * so it is worth setting aside first. Figures set right in reading (a count below zero brought
 * up to it) are not counted; nor is a nothing (zero, false, empty) that the read-back leaves out.
 */
final class Unread
{
	private Unread()
	{
	}

	/** True when the save holds anything that reading it back left out. */
	static boolean any(Gson gson, String saved, Object read)
	{
		try
		{
			return lost(gson.fromJson(saved, JsonElement.class), gson.toJsonTree(read));
		}
		catch (RuntimeException e)
		{
			return true;
		}
	}

	private static boolean lost(JsonElement saved, JsonElement back)
	{
		if (nothing(saved))
		{
			return false;
		}
		if (back == null || back.isJsonNull())
		{
			return true;
		}
		if (saved.isJsonObject())
		{
			if (!back.isJsonObject())
			{
				return true;
			}
			JsonObject b = back.getAsJsonObject();
			for (Map.Entry<String, JsonElement> e : saved.getAsJsonObject().entrySet())
			{
				if (lost(e.getValue(), b.get(e.getKey())))
				{
					return true;
				}
			}
			return false;
		}
		if (saved.isJsonArray())
		{
			if (!back.isJsonArray())
			{
				return true;
			}
			JsonArray s = saved.getAsJsonArray();
			JsonArray b = back.getAsJsonArray();
			if (s.size() > b.size())
			{
				return true;
			}
			// Reading can add to a list (a field an older save had not yet) but not take from it;
			// a list read back the same length is checked item by item.
			if (s.size() == b.size())
			{
				for (int i = 0; i < s.size(); i++)
				{
					if (lost(s.get(i), b.get(i)))
					{
						return true;
					}
				}
			}
			return false;
		}
		// A figure: kept when the read-back has one in its place, set right or not.
		return !back.isJsonPrimitive();
	}

	private static boolean nothing(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return true;
		}
		if (e.isJsonPrimitive())
		{
			JsonPrimitive p = e.getAsJsonPrimitive();
			if (p.isBoolean())
			{
				return !p.getAsBoolean();
			}
			if (p.isNumber())
			{
				return p.getAsBigDecimal().signum() == 0;
			}
			return p.getAsString().isEmpty();
		}
		return e.isJsonArray() ? e.getAsJsonArray().size() == 0 : e.getAsJsonObject().size() == 0;
	}
}

package com.codex.ironworks.core;

/** Where something left the stores to. */
public enum Use
{
	CONSUMED("Eaten and drunk", true),
	CAST("Cast", true),
	FIRED("Fired", true),
	MADE_INTO("Made into", true),
	PLANTED("Planted", true),
	OFFERED("Offered", true),
	SPENT("Spent at shops", true),
	USED("Used", true),
	SOLD("Sold", false),
	TRADED("Traded away", false),
	DROPPED("Dropped", false),
	DIED("Lost on death", false);

	private final String label;
	private final boolean burn;

	Use(String label, boolean burn)
	{
		this.label = label;
		this.burn = burn;
	}

	public String getLabel()
	{
		return label;
	}

	/**
	 * Whether this is the stores being worked through, which sets how long they last. Selling,
	 * trading, dropping and dying are one-off choices or accidents, not the pace of play.
	 */
	public boolean isBurn()
	{
		return burn;
	}

	/** Reads a saved name; null for one this version does not know. */
	public static Use of(String name)
	{
		for (Use u : values())
		{
			if (u.name().equals(name))
			{
				return u;
			}
		}
		return null;
	}
}

package com.codex.ironworks.core;

import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

/**
 * One item a shop sells: its usual stock, what the player has bought of it, and how fast the shop
 * puts it back, learned by watching the stock climb. Shops keep stock per world, so each world is
 * remembered on its own.
 */
public final class Ware
{
	/** Worlds remembered per item; enough for a hopping run, without the save growing for ever. */
	static final int WORLDS = 40;
	/** Readings further apart than this say nothing reliable about the pace of restocking. */
	static final long LONGEST = 3 * 60 * 60_000L;
	/** Readings closer than this are too coarse to time a restock by. */
	static final long SHORTEST = 3_000L;
	/** Purchases kept to learn the price by. */
	static final int PRICES = 16;

	int item;
	String name;
	/** The usual stock: the most ever seen. */
	int base;
	long bought;
	/** Coins and tokens paid for it, by the currency's store. */
	Map<String, Long> spent = new HashMap<>();
	/** Milliseconds for one more to come back into stock, or 0 while not yet known. */
	double restockMs;
	int samples;
	/** The last stock seen on each world. */
	Map<String, Seen> worlds = new HashMap<>();
	/** Purchases with coins: the stock before, how many, and the coins paid, newest last. */
	java.util.List<long[]> prices = new java.util.ArrayList<>();

	/** A stock reading. */
	public static final class Seen
	{
		int stock;
		long at;

		Seen(int stock, long at)
		{
			this.stock = stock;
			this.at = at;
		}

		public int getStock()
		{
			return stock;
		}

		public long getAt()
		{
			return at;
		}
	}

	Ware()
	{
	}

	Ware(int item, String name)
	{
		this.item = item;
		this.name = name;
	}

	/** The shop shows this much in stock on this world now. */
	void observe(int world, int stock, long now)
	{
		if (stock < 0)
		{
			return;
		}
		base = Math.max(base, stock);
		String w = String.valueOf(world);
		Seen prev = worlds.get(w);
		if (prev != null && stock > prev.stock && prev.stock < base)
		{
			long gap = now - prev.at;
			if (gap >= SHORTEST && gap <= LONGEST)
			{
				double perUnit = gap / (double) (stock - prev.stock);
				if (stock < base)
				{
					// Still climbing, so the whole gap was restocking: a true measure.
					restockMs = samples == 0 ? perUnit : restockMs * 0.7 + perUnit * 0.3;
					samples++;
				}
				else if (restockMs == 0 || restockMs > perUnit)
				{
					// Back to full: it restocked at least this fast, perhaps faster.
					restockMs = perUnit;
				}
			}
		}
		if (prev == null || prev.stock != stock || now - prev.at > SHORTEST)
		{
			worlds.put(w, new Seen(stock, now));
		}
		while (worlds.size() > WORLDS)
		{
			Iterator<Map.Entry<String, Seen>> it = worlds.entrySet().iterator();
			Map.Entry<String, Seen> oldest = it.next();
			for (Map.Entry<String, Seen> e : worlds.entrySet())
			{
				if (e.getValue().at < oldest.getValue().at)
				{
					oldest = e;
				}
			}
			worlds.remove(oldest.getKey());
		}
	}

	void bought(long qty, Map<String, Long> paid)
	{
		bought += qty;
		paid.forEach((k, v) -> spent.merge(k, v, Long::sum));
	}

	/** A purchase with coins, for learning how the price climbs as the stock falls. */
	void price(int stockBefore, long qty, long coins)
	{
		if (qty <= 0 || coins <= 0 || stockBefore <= 0)
		{
			return;
		}
		prices.add(new long[]{stockBefore, qty, coins});
		while (prices.size() > PRICES)
		{
			prices.remove(0);
		}
	}

	/** How the price climbs, as learned from purchases, or null before any. */
	public Price price()
	{
		return Price.fit(prices, base);
	}

	/** The stock expected on a world now, or -1 when that world was never seen. */
	public int expected(int world, long now)
	{
		Seen s = worlds.get(String.valueOf(world));
		if (s == null)
		{
			return -1;
		}
		if (restockMs <= 0 || s.stock >= base)
		{
			return s.stock;
		}
		long back = (long) ((now - s.at) / restockMs);
		return (int) Math.min(base, s.stock + back);
	}

	/** When a world will be back to its usual stock, or 0 when it already is or the pace is unknown. */
	public long fullAt(int world)
	{
		Seen s = worlds.get(String.valueOf(world));
		if (s == null || s.stock >= base || restockMs <= 0)
		{
			return 0;
		}
		return s.at + (long) Math.ceil((base - s.stock) * restockMs);
	}

	/** How long an emptied shop takes to fill again, or 0 while unknown. */
	public long refillMs()
	{
		return restockMs <= 0 ? 0 : (long) (restockMs * base);
	}

	public int getItem()
	{
		return item;
	}

	public String getName()
	{
		return name;
	}

	public int getBase()
	{
		return base;
	}

	public long getBought()
	{
		return bought;
	}

	public Map<String, Long> getSpent()
	{
		return spent;
	}

	public double getRestockMs()
	{
		return restockMs;
	}

	public Map<String, Seen> getWorlds()
	{
		return worlds;
	}

	Ware repair()
	{
		base = Math.max(0, base);
		bought = Math.max(0, bought);
		if (Double.isNaN(restockMs) || Double.isInfinite(restockMs) || restockMs < 0)
		{
			restockMs = 0;
		}
		spent = spent == null ? new HashMap<>() : spent;
		spent.values().removeIf(v -> v == null || v <= 0);
		spent.keySet().removeIf(k -> k == null);
		worlds = worlds == null ? new HashMap<>() : worlds;
		worlds.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || e.getValue().stock < 0);
		prices = prices == null ? new java.util.ArrayList<>() : prices;
		prices.removeIf(p -> p == null || p.length != 3 || p[0] <= 0 || p[1] <= 0 || p[2] <= 0);
		return this;
	}
}

