/**
 * A gilt plaque in the game view while a shop is open: what the stores need from this shop, how
 * much it has, and when an emptied world fills again. It draws what the plugin hands it.
 */
public class ShopPlaque extends Overlay
{
	private static final int PAD = 7;
	private static final int ICON = 16;
	private static final int GAP = 12;

	private volatile Shown shown;

	/** One line of the plaque. */
	public static final class Row
	{
		final String name;
		final String figure;
		final String note;
		final Color color;

		/**
		 * @param name the item, such as "Feather pack"
		 * @param figure the stock now, such as "8 / 10"
		 * @param note what to do, such as "Buy 24 for 10h of play"
		 */
		public Row(String name, String figure, String note, Color color)
		{
			this.name = name;
			this.figure = figure;
			this.note = note;
			this.color = color;
		}
	}

	private static final class Shown
	{
		final String title;
		final String subtitle;
		final List<Row> rows;

		Shown(String title, String subtitle, List<Row> rows)
		{
			this.title = title;
			this.subtitle = subtitle;
			this.rows = rows;
		}
	}

	public ShopPlaque()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/** @param title the shop's name, or null to hide the plaque */
	public void show(String title, String subtitle, List<Row> rows)
	{
		shown = title == null || rows == null || rows.isEmpty() ? null
			: new Shown(title, subtitle, Collections.unmodifiableList(rows));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Shown s = shown;
		if (s == null)
		{
			return null;
		}
		Theme.smooth(g);
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();

		int nameW = 0;
		int figureW = 0;
		int noteW = small.stringWidth(s.subtitle == null ? "" : s.subtitle);
		for (Row r : s.rows)
		{
			nameW = Math.max(nameW, small.stringWidth(r.name));
			figureW = Math.max(figureW, small.stringWidth(r.figure));
			noteW = Math.max(noteW, small.stringWidth(r.note));
		}
		int textW = Math.max(bold.stringWidth(s.title), Math.max(nameW + GAP + figureW, noteW));
		int width = PAD + ICON + 7 + textW + PAD;
		int rowH = small.getHeight() * 2 + 3;
		int head = bold.getHeight() + (s.subtitle == null ? 0 : small.getHeight());
		int height = PAD + head + 4 + s.rows.size() * rowH + PAD - 2;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, width - 1, height - 1, 10, 10);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 230), 0, height, Theme.alpha(Theme.INK_DEEP, 230)));
		g.fill(shape);
		g.setColor(Theme.alpha(Theme.GOLD, 150));
		g.draw(shape);

		Sigil.paint(g, PAD, PAD, ICON);
		int x = PAD + ICON + 7;
		int y = PAD + bold.getAscent() - 2;
		g.setFont(Theme.title());
		Ui.shadowed(g, s.title, x, y, Theme.GOLD_BRIGHT);
		g.setFont(Theme.small());
		if (s.subtitle != null)
		{
			y += small.getHeight();
			Ui.shadowed(g, s.subtitle, x, y, Theme.TEXT_MUTED);
		}
		y += 4;
		for (Row r : s.rows)
		{
			g.setColor(Theme.alpha(Theme.GOLD, 50));
			g.drawLine(x, y + 2, x + textW, y + 2);
			y += small.getHeight() + 1;
			Ui.shadowed(g, r.name, x, y, Theme.TEXT);
			Ui.shadowed(g, r.figure, x + textW - small.stringWidth(r.figure), y, r.color);
			y += small.getHeight() + 1;
			Ui.shadowed(g, r.note, x, y, Theme.TEXT_MUTED);
			y += 1;
		}
		return new Dimension(width, height);
	}
}

package com.codex.ironworks.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.ironworks.ui;

import java.util.Collections;
import java.util.Set;
import java.util.WeakHashMap;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Which item pictures have arrived. RuneLite runs a picture's loaded callback again, a moment
 * later, for every ask after it has loaded; a panel that rebuilds or repaints on that callback
 * and asks again as it does would go round for as long as it is shown. Once a picture is in,
 * nothing waits on it any more.
 *
 * <p>Pictures are told apart by the picture itself, not the item: RuneLite keeps only the last
 * 128 item pictures, so one asked for again after a busy while is a new, blank picture that has
 * to be waited on like the first. They are held weakly, so a forgotten picture is not kept.
 * Safe from any thread.
 */
public final class Arrivals
{
	private final Set<AsyncBufferedImage> arrived = Collections.synchronizedSet(Collections.newSetFromMap(new WeakHashMap<>()));

	/** Whether this picture has arrived, so there is nothing to wait for. */
	public boolean arrived(AsyncBufferedImage image)
	{
		return arrived.contains(image);
	}

	/**
	 * Runs onLoaded once the picture is in, unless it already is. A picture that arrives between
	 * the check and the ask still answers: RuneLite then runs the callback a moment later.
	 */
	public void ask(AsyncBufferedImage image, Runnable onLoaded)
	{
		if (image == null || arrived.contains(image))
		{
			return;
		}
		image.onLoaded(() ->
		{
			arrived.add(image);
			if (onLoaded != null)
			{
				onLoaded.run();
			}
		});
	}
}

package com.codex.ironworks.ui;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;

/** A slim engraved progress bar, ember when just begun, gold midway, teal near the end and green when done. */
final class Bar
{
	private Bar()
	{
	}

	static void paint(Graphics2D g, int x, int y, int width, int height, double progress)
	{
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(x, y, width, height, height, height));
		float fill = (float) (width * Math.max(0, Math.min(1, progress)));
		if (fill > 0)
		{
			Color c = Theme.progressColor(progress);
			g.setPaint(new GradientPaint(x, 0, Theme.mix(c, Theme.INK, 0.4), x + width, 0, c));
			g.fill(new RoundRectangle2D.Float(x, y, Math.max(height, fill), height, height, height));
			g.setColor(Theme.alpha(Color.WHITE, 40));
			g.drawLine(x + 1, y, Math.round(x + Math.max(height, fill)) - 2, y);
		}
	}
}

package com.codex.ironworks.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.ironworks.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.ironworks.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
