/**
 * The crest at the top of the panel: the Ironworks medallion, the share of the stores the player
 * made with their own hands in large gilt figures, a thin bar of it, and the store that runs out
 * first.
 */
public class Crest extends JComponent
{
	private static final int HEIGHT = 104;

	private String heading = "IRONWORKS";
	private String figure = "-";
	private String unit = "";
	private String status = "Log in to open the ironworks";
	private String shortStatus;
	private Color statusColor = Theme.TEXT_MUTED;
	private Color tint = Theme.GOLD_DIM;
	private double progress = -1;

	public Crest()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/**
	 * @param figure the large figure, such as "82%"
	 * @param unit a quiet word after it, such as "self-made"
	 * @param progress 0 to 1 for the bar under the figure, or negative for none
	 */
	public void update(String heading, String figure, String unit, double progress, String status, Color statusColor, Color tint)
	{
		update(heading, figure, unit, progress, status, null, statusColor, tint);
	}

	/** @param shortStatus a shorter line for when the status does not fit, or null */
	public void update(String heading, String figure, String unit, double progress, String status, String shortStatus, Color statusColor, Color tint)
	{
		this.shortStatus = shortStatus;
		this.heading = heading;
		this.figure = figure;
		this.unit = unit;
		this.progress = progress;
		this.status = status;
		this.statusColor = statusColor;
		this.tint = tint;
		repaint();
	}

	/**
	 * Draws text at twice the size of the game's bold font by doubling every pixel, the way the
	 * game itself draws large numbers, so the figures stay crisp instead of being re-rasterised.
	 *
	 * @return the width drawn
	 */
	/** How wide {@link #paintLarge} draws the text. */
	static int largeWidth(java.awt.Component c, String text)
	{
		return 2 * Math.max(1, c.getFontMetrics(Theme.title()).stringWidth(text) + 1);
	}

	static int paintLarge(Graphics2D g, String text, int x, int y, Color tint)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, base - fm.getAscent() + 3, Theme.mix(tint, Color.WHITE, 0.35), 0, base, tint));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, y - 2 * fm.getAscent() + 22, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// The medallion: a gilt ring with the mark inside, lit from above.
		int mx = 10;
		int my = 14;
		int md = 54;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, md - 2, md - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 11, my + 11, md - 22);

		int tx = mx + md + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);

		int top = 27;
		int figureW = paintLarge(g, figure, tx, top, tint);
		if (unit != null && !unit.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.GOLD_DIM);
			g.drawString(Ui.clip(unit, small, Math.max(0, room - figureW - 3)), tx + figureW + 3, top + 18);
		}
		if (progress >= 0)
		{
			Bar.paint(g, tx, top + 30, room, 4, progress);
		}
		g.setFont(Theme.small());
		if (status != null)
		{
			String line = shortStatus != null && small.stringWidth(status) > room ? shortStatus : status;
			Ui.shadowed(g, Ui.clip(line, small, room), tx, top + 50, statusColor);
		}

		// The gilt rule under the crest, with a diamond at its middle.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.codex.ironworks.ui;

import java.awt.Dimension;
import javax.swing.JComponent;

/**
 * A painted component whose height follows its width, so text can wrap instead of being cut.
 * Before it has a width it guesses one; once laid out at a different width it asks for another
 * layout at the height that width needs.
 */
abstract class Fitted extends JComponent
{
	/** The width guessed before the first layout: a card's inside in the side panel. */
	static final int GUESS = IronworksPanel.WIDTH - 26;

	Fitted()
	{
		setOpaque(false);
	}

	/** The height the component needs at this width. */
	abstract int heightFor(int width);

	@Override
	public Dimension getPreferredSize()
	{
		if (isPreferredSizeSet())
		{
			return super.getPreferredSize();
		}
		int w = getWidth() > 0 ? getWidth() : GUESS;
		return new Dimension(10, heightFor(w));
	}

	@Override
	@SuppressWarnings("deprecation")
	public void reshape(int x, int y, int w, int h)
	{
		int was = getWidth();
		super.reshape(x, y, w, h);
		if (w > 0 && w != was && heightFor(w) != h)
		{
			revalidate();
		}
	}
}

package com.codex.ironworks.ui;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** Coins, changes, durations and dates in the short forms the panel uses. */
public final class Format
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("EEEE d MMMM yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter SHORT = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter MONTH = DateTimeFormatter.ofPattern("MMM yy", Locale.ENGLISH);

	private Format()
	{
	}

	/**
	 * As every Codex plugin writes figures: in full below 10,000, whole k below a million, M to one
	 * decimal, B to two: "8,240", "41k", "412k", "1.2M", "2.10B". Rounding that reaches the next
	 * unit is written in it, so 999,600 reads "1.0M", never "1000k".
	 */
	public static String amount(long n)
	{
		if (n < 0)
		{
			return "-" + amount(n == Long.MIN_VALUE ? Long.MAX_VALUE : -n);
		}
		if (n < 10_000)
		{
			return String.format(Locale.ENGLISH, "%,d", n);
		}
		long k = Math.round(n / 1_000.0);
		if (k < 1_000)
		{
			return k + "k";
		}
		long tenths = Math.round(n / 100_000.0);
		if (tenths < 10_000)
		{
			return tenths / 10 + "." + tenths % 10 + "M";
		}
		long hundredths = Math.round(n / 10_000_000.0);
		return String.format(Locale.ENGLISH, "%,d", hundredths / 100) + "." + String.format(Locale.ENGLISH, "%02d", hundredths % 100) + "B";
	}

	/**
	 * Held against wanted, {held, wanted}, in the short form; while short, never two figures that
	 * read the same, so 10,450 of 10,499 is written in full rather than "10k / 10k".
	 */
	public static String[] pair(long have, long want)
	{
		String h = amount(have);
		String w = amount(want);
		if (have < want && h.equals(w))
		{
			return new String[]{String.format(Locale.ENGLISH, "%,d", have), String.format(Locale.ENGLISH, "%,d", want)};
		}
		return new String[]{h, w};
	}

	/** Coins in the short form, negative amounts with a minus: "812.4M", "-45k". */
	public static String coins(long gp)
	{
		return gp < 0 ? "-" + amount(-gp) : amount(gp);
	}

	/** A change with its sign: "+3.2M", "-412k", "0". */
	public static String signed(long gp)
	{
		return gp > 0 ? "+" + amount(gp) : gp < 0 ? "-" + amount(-gp) : "0";
	}

	/** A quantity change with its sign, written in full: "+1,240", "-6". */
	public static String count(long n)
	{
		return (n > 0 ? "+" : n < 0 ? "-" : "") + String.format(Locale.ENGLISH, "%,d", Math.abs(n));
	}

	/** A count of trips, or "999+" past what is worth counting. */
	public static String trips(int n)
	{
		if (n >= 1000)
		{
			return "999+";
		}
		return String.valueOf(n);
	}

	/** A trip's use of a supply: whole when it is, otherwise to one place, "16", "13.5". */
	public static String perTrip(double n)
	{
		if (n >= 100 || Math.abs(n - Math.round(n)) < 0.05)
		{
			return String.format(Locale.ENGLISH, "%,d", Math.round(n));
		}
		return trim(n, 1);
	}

	/** A share as a whole percent, or "<1%". */
	public static String percent(double share)
	{
		if (share > 0 && share < 0.01)
		{
			return "<1%";
		}
		// Just short of whole is not whole: 99.6% reads 99%.
		return Math.min(share < 1 ? 99 : 100, Math.round(share * 100)) + "%";
	}

	/** "just now", "12m ago", "3h ago", "2d ago". */
	public static String ago(long ms)
	{
		long minutes = Math.max(0, ms) / 60_000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		if (minutes < 48 * 60)
		{
			return minutes / 60 + "h ago";
		}
		return minutes / (24 * 60) + "d ago";
	}

	private static String trim(double value, int places)
	{
		String text = String.format(Locale.ENGLISH, "%." + places + "f", value);
		while (text.contains(".") && (text.endsWith("0") || text.endsWith(".")))
		{
			text = text.substring(0, text.length() - 1);
		}
		return text;
	}

	/** "2h 14m", "38m", "under a minute". */
	public static String duration(long ms)
	{
		long minutes = ms / 60_000;
		if (minutes < 1)
		{
			return "under a minute";
		}
		if (minutes < 60)
		{
			return minutes + "m";
		}
		return minutes / 60 + "h " + minutes % 60 + "m";
	}

	/** A rough time to come: "<1m", "25m", "3h 10m", "41h". */
	public static String estimate(long ms)
	{
		long minutes = Math.round(ms / 60_000.0);
		if (minutes < 1)
		{
			return "<1m";
		}
		if (minutes < 60)
		{
			return minutes + "m";
		}
		if (minutes < 10 * 60)
		{
			return minutes / 60 + "h " + minutes % 60 + "m";
		}
		return Math.round(minutes / 60.0) + "h";
	}

	/** "14:02" in the player's own time. */
	public static String time(long epochMs)
	{
		return CLOCK.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct". */
	public static String day(long epochMs)
	{
		return DAY.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "16 Oct". */
	public static String shortDay(long epochMs)
	{
		return SHORT.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Oct 26". */
	public static String month(long epochMs)
	{
		return MONTH.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct" for a day book date. */
	public static String day(java.time.LocalDate date)
	{
		return DAY.format(date);
	}

	/** "Thursday 16 October 2026". */
	public static String date(long epochMs)
	{
		return DATE.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** An item stack the way the game writes it: "950", "45K", "12M". */
	public static String stack(long n)
	{
		if (n < 100_000)
		{
			return String.valueOf(n);
		}
		if (n < 10_000_000)
		{
			return n / 1_000 + "K";
		}
		return n / 1_000_000 + "M";
	}

	/** The colour the game writes a stack of that size in. */
	public static java.awt.Color stackColor(long n)
	{
		return n < 100_000 ? Theme.QTY_YELLOW : n < 10_000_000 ? Theme.QTY_WHITE : Theme.QTY_GREEN;
	}

	/** A short wait in seconds: "0.6s", "6.2s", "42s", "1m 20s". */
	public static String seconds(double ms)
	{
		if (ms < 10_000)
		{
			return trim(Math.max(0, ms) / 1000.0, 1) + "s";
		}
		long s = Math.round(ms / 1000.0);
		if (s < 60)
		{
			return s + "s";
		}
		return s / 60 + "m" + (s % 60 == 0 ? "" : " " + s % 60 + "s");
	}
}

package com.codex.ironworks.ui;

import com.codex.ironworks.core.Death;
import com.codex.ironworks.core.Family;
import com.codex.ironworks.core.Runway;
import com.codex.ironworks.core.Source;
import com.codex.ironworks.core.Spot;
import com.codex.ironworks.core.Summary;
import com.codex.ironworks.core.Use;
import com.codex.ironworks.core.Ways;
import com.codex.ironworks.core.Workshop;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.api.Experience;
import javax.swing.ScrollPaneConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Ironworks side panel: the crest, then five pages. Stores is every store with how long it
 * lasts at the player's own pace; Make is what the stores could become and the experience in them;
 * Find is everything the account owns, wherever it is kept, and the last death's items; Sources is
 * where everything came from and the ways to get more; Shops is the shopping list, the shops the
 * player uses with their restock times and prices, and past shop runs.
 */
public class IronworksPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"stores", "make", "find", "sources", "shops"};
	private static final int STORES = 0;
	private static final int MAKE = 1;
	private static final int FIND = 2;
	private static final int SOURCES = 3;
	private static final int SHOPS = 4;
	/** Things found shown before the list is cut short. */
	private static final int FOUND = 60;
	/** Stores shown per shelf before "Show all". */
	private static final int SHELF = 6;

	private final ItemIcons icons;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(false, "Stores", "Make", "Find", "Sources", "Shops");
	private final Segmented period = new Segmented(false, "Today", "7 days", "All time");
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane[] pages = {scroller(), scroller(), scroller(), scroller(), scroller()};
	private final boolean[] stale = {true, true, true, true, true};
	private final JTextField search = new SearchField();
	private final Runnable forgetDeath;
	private final Set<String> open = new HashSet<>();
	private final Set<Family> shelvesOpen = new HashSet<>();

	private View view = new View();

	public IronworksPanel(ItemIcons icons, Runnable forgetDeath)
	{
		super(false);
		this.icons = icons;
		this.forgetDeath = forgetDeath;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		for (int i = 0; i < TABS.length; i++)
		{
			if (i == FIND)
			{
				JPanel find = new JPanel(new BorderLayout());
				find.setOpaque(false);
				JPanel holder = new JPanel(new BorderLayout());
				holder.setOpaque(false);
				holder.setBorder(new EmptyBorder(6, 8, 0, 8));
				holder.add(search, BorderLayout.CENTER);
				find.add(holder, BorderLayout.NORTH);
				find.add(pages[i], BorderLayout.CENTER);
				content.add(find, TABS[i]);
			}
			else
			{
				content.add(pages[i], TABS[i]);
			}
		}
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rebuild(FIND);
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rebuild(FIND);
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rebuild(FIND);
			}
		});
		add(content, BorderLayout.CENTER);
		tabs.onChange(this::showTab);
		period.setSelected(1, false);
		period.onChange(i ->
		{
			stale[SOURCES] = true;
			refresh(true);
		});
		updateCrest();
		refresh(true);
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/** Called on the Swing thread whenever anything shown changes. */
	public void show(View view)
	{
		this.view = view;
		updateCrest();
		java.util.Arrays.fill(stale, true);
		refresh(false);
	}

	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
		refresh(true);
	}

	/** For the screenshot harness: types into Find. */
	public void find(String text)
	{
		search.setText(text);
	}

	/** For the screenshot harness: picks the Sources period. */
	public void showPeriod(int index)
	{
		period.setSelected(index, true);
	}

	@Override
	public void onActivate()
	{
		refresh(true);
	}

	/** Rebuilds the page in view if it is out of date; nothing is rebuilt while the panel is closed. */
	private void refresh(boolean force)
	{
		if (!force && !isShowing())
		{
			return;
		}
		int page = tabs.getSelected();
		if (!stale[page])
		{
			return;
		}
		stale[page] = false;
		JComponent body = page == STORES ? stores() : page == MAKE ? workshop() : page == FIND ? find()
			: page == SOURCES ? sources() : shops();
		JScrollPane scroll = pages[page];
		int y = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(body);
		scroll.revalidate();
		scroll.getVerticalScrollBar().setValue(y);
		scroll.repaint();
	}

	private void rebuild(int page)
	{
		stale[page] = true;
		refresh(true);
	}

	// ---- the crest ----

	private void updateCrest()
	{
		View v = view;
		String heading = Words.account(v.account).toUpperCase(Locale.ENGLISH);
		if (!v.loggedIn && v.stores.isEmpty())
		{
			crest.update("IRONWORKS", "-", "", -1, "Log in to open the ironworks", Theme.TEXT_MUTED, Theme.GOLD_DIM);
			return;
		}
		Summary s = v.week;
		boolean known = s != null && s.self >= 0;
		String figure = known ? Format.percent(s.self) : "-";
		String unit = known ? "self-made" : "";
		Runway first = null;
		int wanting = 0;
		for (View.StoreView sv : v.stores)
		{
			if (sv.runway.wanting() && !com.codex.ironworks.core.Catalogue.money(sv.store))
			{
				wanting++;
				if (first == null || sv.runway.hours < first.hours)
				{
					first = sv.runway;
				}
			}
		}
		String status;
		String shortStatus = null;
		Color color;
		if (v.playedWeek < Runway.LEARN_MS)
		{
			status = "Measuring your pace: " + Format.duration(v.playedWeek) + " of 1h";
			color = Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.3);
		}
		else if (first == null)
		{
			status = "Every store lasts " + Math.round(v.target) + "h or more";
			color = Theme.TEAL;
		}
		else if (first.status == Runway.Status.OUT)
		{
			status = first.store + " is out";
			shortStatus = wanting == 1 ? "A store is out" : wanting + " stores short, one out";
			color = Theme.BLOOD;
		}
		else
		{
			status = first.store + " runs out in " + Words.runway(first) + (wanting > 1 ? " · " + wanting + " short" : "");
			shortStatus = wanting + " short · first in " + Words.runway(first);
			color = Palette.of(first.status);
		}
		crest.update(heading, figure, unit, known ? s.self : -1, status, shortStatus, color, known ? Theme.progressColor(s.self) : Theme.GOLD_DIM);
	}

	// ---- stores ----

	private JComponent stores()
	{
		StackPanel p = new StackPanel(6, 8);
		View v = view;
		if (v.stores.isEmpty())
		{
			p.add(note(v.loggedIn
				? "Your stores fill in as you play. Open your bank once so Ironworks can count what you keep."
				: "Log in to see your stores: how long each lasts at your pace, and where it all came from."));
			return p;
		}
		if (!v.bankSeen)
		{
			p.add(note("Open your bank so the stores count what you keep there, not only what you carry."));
		}
		List<View.StoreView> low = new ArrayList<>();
		Map<Family, List<View.StoreView>> shelves = new EnumMap<>(Family.class);
		for (View.StoreView s : v.stores)
		{
			if (s.runway.wanting() && !com.codex.ironworks.core.Catalogue.money(s.store))
			{
				low.add(s);
			}
			else if (s.stock > 0 || s.week.gained() > 0 || s.week.burned() > 0)
			{
				shelves.computeIfAbsent(s.family, k -> new ArrayList<>()).add(s);
			}
		}
		if (!low.isEmpty())
		{
			low.sort((a, b) -> Double.compare(a.runway.hours, b.runway.hours));
			p.add(new SectionHeader("Running short", low.size() + " under " + Math.round(v.target) + "h"));
			for (View.StoreView s : low)
			{
				p.add(row(s));
			}
		}
		for (Map.Entry<Family, List<View.StoreView>> e : shelves.entrySet())
		{
			Family f = e.getKey();
			List<View.StoreView> list = e.getValue();
			p.add(new SectionHeader(f.getLabel(), String.valueOf(list.size())));
			boolean all = shelvesOpen.contains(f) || list.size() <= SHELF + 1;
			for (int i = 0; i < list.size() && (all || i < SHELF); i++)
			{
				p.add(row(list.get(i)));
			}
			if (list.size() > SHELF + 1)
			{
				JPanel holder = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
				holder.setOpaque(false);
				holder.add(new CodexButton(all ? "Show fewer" : "Show all " + list.size(), false, () ->
				{
					if (!shelvesOpen.remove(f))
					{
						shelvesOpen.add(f);
					}
					rebuild(STORES);
				}));
				p.add(holder);
			}
		}
		p.add(foot("Runways are hours of your own play, measured over the last 7 days."));
		return p;
	}

	private JComponent row(View.StoreView s)
	{
		return new StoreRow(s, view, icons, open.contains(s.store), () ->
		{
			if (!open.remove(s.store))
			{
				open.add(s.store);
			}
			rebuild(STORES);
		});
	}

	// ---- sources ----

	private JComponent sources()
	{
		StackPanel p = new StackPanel(6, 8);
		p.add(period);
		View v = view;
		Summary s = period.getSelected() == 0 ? v.today : period.getSelected() == 1 ? v.week : v.all;
		if (s == null || s.gained <= 0 && s.used <= 0)
		{
			p.add(note(v.loggedIn || !v.stores.isEmpty()
				? "Nothing has come in or gone out " + (period.getSelected() == 0 ? "today" : period.getSelected() == 1 ? "this week" : "yet")
				+ ". Gather, make, loot or buy something and it shows here."
				: "Log in to see where your supplies come from."));
			getMore(p);
			return p;
		}
		if (s.gained > 0)
		{
			p.add(selfCard(s));
		}
		getMore(p);
		if (!s.skills.isEmpty())
		{
			Card hands = new Card(new BorderLayout());
			StackPanel in = new StackPanel(2, 0);
			in.add(new SectionHeader("Your own hands", "by worth"));
			double total = 0;
			for (double d : s.skills.values())
			{
				total += d;
			}
			List<Map.Entry<String, Double>> list = new ArrayList<>(s.skills.entrySet());
			list.sort((a, b) -> Double.compare(b.getValue(), a.getValue()));
			for (Map.Entry<String, Double> e : list.subList(0, Math.min(6, list.size())))
			{
				in.add(new Meter(e.getKey(), Format.percent(e.getValue() / total), e.getValue() / total, Theme.TEAL));
			}
			hands.add(in, BorderLayout.CENTER);
			p.add(hands);
		}
		for (Source src : Source.values())
		{
			List<Summary.Line> lines = s.bySource.get(src);
			if (lines == null || lines.isEmpty())
			{
				continue;
			}
			p.add(itemsCard(src.getLabel(), Format.percent(s.sources.get(src) / s.gained), Palette.of(src), lines, true));
		}
		if (s.used > 0)
		{
			Card went = new Card(new BorderLayout());
			StackPanel in = new StackPanel(2, 0);
			in.add(new SectionHeader("Where it went", "by worth"));
			List<Double> parts = new ArrayList<>();
			List<Color> colors = new ArrayList<>();
			for (Use u : Use.values())
			{
				Double d = s.uses.get(u);
				if (d != null && d > 0)
				{
					parts.add(d);
					colors.add(Palette.of(u));
				}
			}
			in.add(new Stacked(parts, colors, 8));
			for (Use u : Use.values())
			{
				Double d = s.uses.get(u);
				List<Summary.Line> lines = s.byUse.get(u);
				if (d != null && d > 0 && lines != null)
				{
					in.add(new Line(u.getLabel(), Format.percent(d / s.used), Palette.of(u), Theme.TEXT, Theme.TEXT_MUTED));
					for (Summary.Line l : lines.subList(0, Math.min(3, lines.size())))
					{
						in.add(new Line("   " + l.store, Format.amount(l.units), null));
					}
				}
			}
			went.add(in, BorderLayout.CENTER);
			p.add(went);
		}
		if (s.played > 0)
		{
			p.add(foot("Over " + Format.duration(s.played) + " of play. Worth is the exchange price; coins are left out."));
		}
		return p;
	}

	private JComponent selfCard(Summary s)
	{
		Card card = new Card(new BorderLayout());
		card.highlighted(true);
		StackPanel in = new StackPanel(3, 0);
		in.add(new Figure(Format.percent(Math.max(0, s.self)), "your own work", Theme.progressColor(Math.max(0, s.self))));
		List<Double> parts = new ArrayList<>();
		List<Color> colors = new ArrayList<>();
		for (Source src : Source.values())
		{
			Double d = s.sources.get(src);
			if (d != null && d > 0)
			{
				parts.add(d);
				colors.add(Palette.of(src));
			}
		}
		in.add(new Stacked(parts, colors, 8));
		for (Source src : Source.values())
		{
			Double d = s.sources.get(src);
			if (d != null && d > 0)
			{
				in.add(new Line(src.getLabel(), Format.amount(Math.round(d)) + "  " + Format.percent(d / s.gained), Palette.of(src)));
			}
		}
		card.add(in, BorderLayout.CENTER);
		return card;
	}

	private JComponent itemsCard(String title, String trailing, Color accent, List<Summary.Line> lines, boolean units)
	{
		Card card = new Card(new BorderLayout());
		card.accent(accent);
		StackPanel in = new StackPanel(2, 0);
		in.add(new SectionHeader(title, trailing));
		JPanel wells = new JPanel(new java.awt.GridLayout(1, 4, 4, 0));
		wells.setOpaque(false);
		int shown = 0;
		for (Summary.Line l : lines)
		{
			if (shown == 4)
			{
				break;
			}
			wells.add(new Slot(view.icons.getOrDefault(l.store, -1), l.units, l.store, icons));
			shown++;
		}
		while (shown++ < 4)
		{
			JPanel blank = new JPanel();
			blank.setOpaque(false);
			wells.add(blank);
		}
		in.add(wells);
		if (lines.size() > 4)
		{
			List<String> rest = new ArrayList<>();
			for (Summary.Line l : lines.subList(4, Math.min(lines.size(), 7)))
			{
				rest.add(l.store);
			}
			in.add(new Line("Also " + String.join(", ", rest) + (lines.size() > 7 ? " and more" : ""), null, null));
		}
		card.add(in, BorderLayout.CENTER);
		return card;
	}

