			g.setFont(getFont());
			FontMetrics fm = g.getFontMetrics();
			int w = getWidth();
			List<String> rows = rows(fm, w);
			Ui.shadowed(g, figure, w - fm.stringWidth(figure), 11, Theme.TEXT_MUTED);
