package com.codex.ironworks.ui;

import com.codex.ironworks.core.Catalogue;
import com.codex.ironworks.core.Runway;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.swing.border.EmptyBorder;

/** A store on the shopping list: how much is needed, and where it was bought or how it is made. */
class WantRow extends Card
{
	WantRow(View.Want w, ItemIcons icons)
	{
		super(new BorderLayout());
		setBorder(new EmptyBorder(4, 6, 4, 8));
		accent(Palette.of(w.status));
		add(new Head(w, icons), BorderLayout.CENTER);
		String how = how(w);
		setToolTipText("<html><b>" + Ui.escape(w.store) + "</b><br>Need " + Format.amount(w.need) + " more<br>" + Ui.escape(how)
			+ (w.shop != null ? " at " + Ui.escape(w.shop) : "")
			+ (w.refillMs > 0 ? "<br>The shop refills in about " + Format.estimate(w.refillMs) + " once emptied" : "") + "</html>");
	}

	/** What to do about it: buy so many at a shop, make it, or nothing known yet. */
	static String how(View.Want w)
	{
		if (w.shop != null)
		{
			long items = (w.need + w.units - 1) / Math.max(1, w.units);
			return "Buy " + Format.amount(items) + " \u00d7 " + w.ware;
		}
		if (w.skill != null)
		{
			return (Catalogue.gathered(w.store) ? "Gather it with " : "Make it with ") + w.skill;
		}
		return "No source seen yet";
	}

	/** The cost in coins, or the player's own pace of getting it, when either is known. */
	static String extra(View.Want w)
	{
		if (w.shop != null && w.coins > 0)
		{
			return Format.coins(w.coins) + " coins" + (w.perWorld > 0 && w.perWorld * w.units < w.need ? ", " + Format.amount(w.perWorld) + " a world" : "");
		}
		if (w.perHour > 0 && w.how != null)
		{
			return "About " + Format.estimate((long) (w.need / w.perHour * 3_600_000)) + " at your " + w.how + " pace";
		}
		return null;
	}

	private static final class Head extends Fitted
	{
		private final View.Want w;
		private final ItemIcons icons;

		Head(View.Want w, ItemIcons icons)
		{
			this.w = w;
			this.icons = icons;
		}

		private String figure()
		{
			return "+" + Format.amount(w.need);
		}

		/** The smaller lines under the name, each with its colour. */
		private Object[][] lines()
		{
			Color color = Palette.of(w.status);
			String when = w.status == Runway.Status.OUT ? "Out now" : "Lasts " + Format.estimate((long) (w.hours * 3_600_000));
			String extra = extra(w);
			return new Object[][]{
				{when, color},
				{how(w), Theme.TEXT_MUTED},
				{w.shop == null ? null : "at " + w.shop, Theme.TEXT_FAINT},
				{extra, Theme.TEAL},
			};
		}

		/** Paints the text, or with no graphics only measures it; returns the height used. */
		private int lay(Graphics2D g, int width)
		{
			int x = Well.SIZE + 10;
			int room = width - x;
			FontMetrics bold = getFontMetrics(Theme.title());
			FontMetrics body = getFontMetrics(Theme.body());
			FontMetrics small = getFontMetrics(Theme.small());
			String figure = figure();
			int fw = bold.stringWidth(figure);
			int y = 15;
			java.util.List<String> name = Ui.wrap(w.store, body, room - fw - 6);
			if (g != null)
			{
				g.setFont(Theme.title());
				Ui.shadowed(g, figure, width - fw, 15, Palette.of(w.status));
				g.setFont(Theme.body());
			}
			for (String row : name)
			{
				if (g != null)
				{
					Ui.shadowed(g, row, x, y, Theme.TEXT);
				}
				y += 13;
			}
			y -= 2;
			if (g != null)
			{
				g.setFont(Theme.small());
			}
			for (Object[] line : lines())
			{
				if (line[0] == null)
				{
					continue;
				}
				for (String row : Ui.wrap((String) line[0], small, room))
				{
					if (g != null)
					{
						Ui.shadowed(g, row, x, y, (Color) line[1]);
					}
					y += 11;
				}
			}
			return y - 8;
		}

		@Override
		int heightFor(int width)
		{
			return Math.max(40, lay(null, width));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			BufferedImage icon = icons == null || w.icon < 0 ? null : icons.icon(w.icon, this::repaint);
			Well.paint(g, 0, 4, icon, Theme.alpha(Palette.of(w.status), 160));
			lay(g, getWidth());
			g.dispose();
		}
	}
}

package com.codex.ironworks.ui;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** The dark slot an item sits in, like a bank slot, with the stack drawn in the game's colours. */
final class Well
{
	static final int SIZE = 32;

	private Well()
	{
	}

	static void paint(Graphics2D g, int x, int y, BufferedImage icon, Color rim)
	{
		RoundRectangle2D well = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, SIZE + 4, SIZE - 1, 7, 7);
		g.setPaint(new GradientPaint(0, y, Theme.INK_DEEP, 0, y + SIZE, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
		g.fill(well);
		g.setColor(rim == null ? Theme.STROKE_SOFT : rim);
		g.draw(well);
		if (icon != null)
		{
			g.drawImage(icon, x + 2 + (SIZE - icon.getWidth()) / 2, y + (SIZE - icon.getHeight()) / 2 + 1, null);
		}
	}
}

package com.codex.ironworks.ui;

import com.codex.ironworks.core.Runway;
import java.util.Locale;

/** The panel's short phrases for runways, rates and account types. */
public final class Words
{
	private Words()
	{
	}

	/** How long a store lasts, in a word or two: "Out", "3h 10m", "41h", "Steady", "Idle". */
	public static String runway(Runway r)
	{
		switch (r.status)
		{
			case OUT:
				return "Out";
			case STEADY:
				return "Steady";
			case IDLE:
				return "Idle";
			case LEARNING:
				return "Learning";
			default:
				return r.hours >= 1000 ? "999h+" : Format.estimate((long) (r.hours * 3_600_000));
		}
	}

	/** A rate per hour played: "0.4", "12", "1,240", "41k". */
	public static String rate(double perHour)
	{
		if (perHour <= 0)
		{
			return "0";
		}
		if (perHour < 10)
		{
			String one = String.format(Locale.ENGLISH, "%.1f", perHour);
			return one.endsWith(".0") ? one.substring(0, one.length() - 2) : one;
		}
		return Format.amount(Math.round(perHour));
	}

	/** The pace under a store: "Uses 42 an hour, gains 12", "Gains 6 an hour", "Not used this week". */
	public static String pace(Runway r)
	{
		if (r.status == Runway.Status.LEARNING)
		{
			return "Measuring your pace";
		}
		if (r.burn <= 0 && r.gain <= 0)
		{
			return "Not used this week";
		}
		if (r.burn <= 0)
		{
			return "Gains " + rate(r.gain) + " an hour";
		}
		return "Uses " + rate(r.burn) + " an hour" + (r.gain > 0 ? ", gains " + rate(r.gain) : "");
	}

	/** The account type from the ironman varbit, as the heading shows it. */
	public static String account(int varbit)
	{
		switch (varbit)
		{
			case 0:
				return "Main account";
			case 1:
				return "Ironman";
			case 2:
				return "Ultimate ironman";
			case 3:
				return "Hardcore ironman";
			case 4:
				return "Group ironman";
			case 5:
				return "Hardcore group ironman";
			case 6:
				return "Unranked group ironman";
			default:
				return "Ironworks";
		}
	}

	/** Hours of play as days at the player's pace: "about 3 days", or null when the pace is unknown. */
	public static String days(double hours, double hoursPerDay)
	{
		if (hoursPerDay <= 0.05 || Double.isInfinite(hours))
		{
			return null;
		}
		double days = hours / hoursPerDay;
		if (days < 1)
		{
			return "under a day at your pace";
		}
		long whole = Math.round(days);
		return "about " + whole + (whole == 1 ? " day" : " days") + " at your pace";
	}
}

package com.codex.ironworks;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Test;

/** Every setting has a short name, one plain sentence and a place of its own, worded as across the suite. */
public class SettingsTest
{
	@Test
	public void everySettingIsNamedAndPlacedClearly()
	{
		Set<String> sections = new HashSet<>();
		for (Field f : CodexIronworksConfig.class.getFields())
		{
			if (f.isAnnotationPresent(ConfigSection.class))
			{
				ConfigSection section = f.getAnnotation(ConfigSection.class);
				assertFalse(section.name().isEmpty());
				assertFalse(section.description().isEmpty());
				try
				{
					sections.add((String) f.get(null));
				}
				catch (IllegalAccessException e)
				{
					throw new AssertionError(e);
				}
			}
		}
		Set<String> places = new HashSet<>();
		Set<String> names = new HashSet<>();
		for (Method m : CodexIronworksConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null || item.hidden())
			{
				continue;
			}
			String name = item.name();
			String description = item.description();
			assertTrue(m.getName(), !name.isEmpty() && name.length() <= 26);
			assertTrue(m.getName(), names.add(name));
			assertTrue(m.getName(), Character.isUpperCase(name.charAt(0)) && !name.endsWith("."));
			assertTrue(m.getName() + " " + description.length(), description.length() >= 20 && description.length() <= 220);
			assertTrue(m.getName(), Character.isUpperCase(description.charAt(0)) && !description.endsWith("."));
			// Top-level settings come first; any other sits in a section that exists.
			assertTrue(m.getName() + " is in no known section", item.section().isEmpty() || sections.contains(item.section()));
			assertTrue(m.getName() + " shares its place", places.add(item.section() + "#" + item.position()));
			if ("nameOnCard".equals(item.keyName()))
			{
				assertEquals("Name on cards", name);
			}
			if ("worthOnCard".equals(item.keyName()))
			{
				assertEquals("Worth on cards", name);
			}
		}
		assertFalse(names.isEmpty());
	}

	@Test
	public void savedSettingsKeepTheirKeys()
	{
		// A setting's key is where its value is saved: renaming one quietly resets it for every player
		// who changed it. These are the keys as released; settings may be added and renamed on screen,
		// but not moved.
		assertEquals("codexironworks", CodexIronworksConfig.GROUP);
		Set<String> keys = new HashSet<>();
		for (Method m : CodexIronworksConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				keys.add(item.keyName());
			}
		}
		for (String key : new String[]{"target", "warn", "chatWarnings", "shopPlaque", "picked", "hidden"})
		{
			assertTrue(key, keys.contains(key));
		}
	}
}

package com.codex.ironworks;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.codex.ironworks.core.Catalogue;
import com.codex.ironworks.core.Flow;
import com.codex.ironworks.core.Place;
import com.codex.ironworks.core.Runway;
import com.codex.ironworks.core.Shop;
import com.codex.ironworks.core.Source;
import com.codex.ironworks.core.Use;
import com.codex.ironworks.core.Works;
import com.codex.ironworks.ui.View;
import java.time.LocalDate;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class ViewsTest
{
	private static final LocalDate TODAY = LocalDate.of(2026, 10, 20);
	private static final long NOW = 1_000_000_000L;

	private static Works feathers()
	{
		Works w = new Works();
		w.played(TODAY, 4 * 3_600_000L);
		w.record(Collections.singletonList(Flow.out("Feather", 2000, Use.MADE_INTO, "Fletching")), TODAY);
		w.record(Collections.singletonList(Flow.in("Feather", 1000, Source.BOUGHT, null)), TODAY);
		Map<String, Long> bank = new HashMap<>();
		bank.put("Feather", 1500L);
		bank.put("Shark", 300L);
		w.place(Place.BANK, bank, NOW);
		Shop s = w.visit("Gerrant's Fishy Business", 12082, 302, NOW - 60_000);
		w.stock(s, 11881, "Feather pack", 302, 10, NOW - 60_000);
		w.purchase(s, 11881, "Feather pack", 10, Collections.singletonMap("Coins", 20_000L), 301, NOW - 60_000);
		w.pack("Feather pack", 100);
		return w;
	}

	@Test
	public void aShortStoreIsListedWithTheShopItWasBoughtAt()
	{
		View v = Views.build(feathers(), Catalogue.standard(), 10, 2, NOW, TODAY, s -> 1);
		assertEquals(1, v.wants.size());
		View.Want want = v.wants.get(0);
		assertEquals("Feather", want.store);
		// 500 an hour for ten hours, 1,500 held: 3,500 more, 35 packs.
		assertEquals(3500, want.need);
		assertEquals("Gerrant's Fishy Business", want.shop);
		assertEquals("Feather pack", want.ware);
		assertEquals(100, want.units);
		assertEquals(Runway.Status.SHORT, want.status);
		View.StoreView feather = null;
		for (View.StoreView s : v.stores)
		{
			if (s.store.equals("Feather"))
			{
				feather = s;
			}
		}
		assertTrue(feather.shops.contains("Gerrant's Fishy Business"));
		assertEquals(1500L, (long) feather.where.get(Place.BANK));
	}

	@Test
	public void hiddenStoresAreLeftOut()
	{
		View v = Views.build(feathers(), Catalogue.with("", "feather"), 10, 2, NOW, TODAY, s -> 1);
		assertTrue(v.wants.isEmpty());
		for (View.StoreView s : v.stores)
		{
			assertTrue(!s.store.equals("Feather"));
		}
	}

	@Test
	public void packsFillTheirStoreAndCoinsFillNone()
	{
		Catalogue.Lookup lookup = Catalogue.standard();
		assertEquals("Feather", Views.storeOf(lookup, "Feather pack"));
		assertEquals("Feather", Views.storeOf(lookup, "Feather"));
		assertNull(Views.storeOf(lookup, "Coins"));
		assertNull(Views.storeOf(lookup, "Lobster pot"));
		Works w = new Works();
		w.pack("Feather pack", 100);
		assertEquals(100, Views.perItem(w, lookup, "Feather pack"));
		assertEquals(4, Views.perItem(w, lookup, "Prayer potion(4)"));
		assertEquals(1, Views.perItem(w, lookup, "Lobster pot"));
	}
}

package com.codex.ironworks.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CatalogueTest
{
	private final Catalogue.Lookup lookup = Catalogue.standard();

	@Test
	public void potionsAreOneStoreCountedInDoses()
	{
		Catalogue.Match four = lookup.match("Prayer potion(4)");
		Catalogue.Match one = lookup.match("Prayer potion(1)");
		assertEquals("Prayer potion", four.store);
		assertEquals(4, four.units);
		assertTrue(four.model);
		assertEquals("Prayer potion", one.store);
		assertEquals(1, one.units);
		assertFalse(one.model);
		assertEquals(Family.POTIONS, four.family);
	}

	@Test
	public void grimyAndCleanHerbsAreOneStore()
	{
		assertEquals("Ranarr weed", lookup.match("Grimy ranarr weed").store);
		assertEquals("Ranarr weed", lookup.match("Ranarr weed").store);
		assertFalse(lookup.match("Grimy ranarr weed").model);
		assertTrue(lookup.match("Ranarr weed").model);
		assertEquals(Family.HERBS, lookup.match("Grimy snapdragon").family);
	}

	@Test
	public void enchantedBoltsAreNotMistakenForDoses()
	{
		Catalogue.Match bolts = lookup.match("Ruby dragon bolts (e)");
		assertEquals("Ruby dragon bolts (e)", bolts.store);
		assertEquals(1, bolts.units);
		assertEquals(Family.AMMO, bolts.family);
	}

	@Test
	public void unknownItemsAreNoStore()
	{
		assertNull(lookup.match("Abyssal whip"));
		assertNull(lookup.match("null"));
		assertNull(lookup.match(""));
		assertNull(lookup.match(null));
		// A dose suffix on something that is not a potion is not a potion.
		assertNull(lookup.match("Games necklace(8)"));
	}

	@Test
	public void picksAndHiddenStoresFollowThePlayer()
	{
		Catalogue.Lookup own = Catalogue.with("Abyssal whip, games necklace(8)\n", "coins,  Feather");
		assertEquals(Family.PICKED, own.match("Abyssal whip").family);
		assertNull(own.match("Coins"));
		assertNull(own.match("Feather"));
		assertEquals("Shark", own.match("Shark").store);
	}

	@Test
	public void packsOpenIntoTheirStore()
	{
		assertEquals("Feather", lookup.packOf("Feather pack"));
		assertEquals("Eye of newt", lookup.packOf("Eye of newt pack"));
		assertEquals("Vial of water", lookup.packOf("Vial of water pack"));
		assertEquals("Air rune", lookup.packOf("Air rune pack"));
		assertNull(lookup.packOf("Shark"));
		assertNull(lookup.packOf("Backpack"));
	}

	@Test
	public void gatheredAndMadeAreToldApart()
	{
		assertTrue(Catalogue.gathered("Raw shark"));
		assertTrue(Catalogue.gathered("Coal"));
		assertTrue(Catalogue.gathered("Ranarr weed"));
		assertFalse(Catalogue.gathered("Shark"));
		assertFalse(Catalogue.gathered("Prayer potion"));
		assertFalse(Catalogue.gathered("Runite bar"));
		assertTrue(Catalogue.money("Coins"));
		assertFalse(Catalogue.money("Shark"));
	}
}

package com.codex.ironworks.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

public class ClassifyTest
{
	private final Map<String, Long> sacks = new HashMap<>();

	private static Map<String, Long> delta(Object... pairs)
	{
		Map<String, Long> m = new LinkedHashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((String) pairs[i], ((Number) pairs[i + 1]).longValue());
		}
		return m;
	}

	private static Classify.Context xp(Skill... skills)
	{
		return new Classify.Context().xp(skills.length == 0 ? EnumSet.noneOf(Skill.class) : EnumSet.copyOf(Arrays.asList(skills)));
	}

	private static Classify.Action click(String option, String target, String store)
	{
		return new Classify.Action(option, target, store, false);
	}

	private Flow only(Map<String, Long> delta, Classify.Context ctx)
	{
		List<Flow> flows = Classify.tick(delta, ctx, sacks);
		assertEquals(flows.toString(), 1, flows.size());
		return flows.get(0);
	}

	@Test
	public void eatingAndDrinkingAreConsumed()
	{
		Flow eat = only(delta("Shark", -1), xp().actions(Collections.singletonList(click("Eat", "<col=ff9040>Shark", "Shark"))));
		assertEquals(Use.CONSUMED, eat.use);
		Flow sip = only(delta("Prayer potion", -1), xp().actions(Collections.singletonList(click("Drink", "Prayer potion(3)", "Prayer potion"))));
		assertEquals(Use.CONSUMED, sip.use);
		assertEquals(1, sip.units);
	}

	@Test
	public void herbloreTurnsInputsIntoAMadePotion()
	{
		List<Flow> flows = Classify.tick(delta("Ranarr potion (unf)", -1, "Snape grass", -1, "Prayer potion", 3), xp(Skill.HERBLORE), sacks);
		assertEquals(3, flows.size());
		for (Flow f : flows)
		{
			if (f.isGain())
			{
				assertEquals(Source.MADE, f.source);
				assertEquals("Herblore", f.skill);
				assertEquals(3, f.units);
			}
			else
			{
				assertEquals(Use.MADE_INTO, f.use);
				assertEquals("Herblore", f.skill);
			}
		}
	}

	@Test
	public void gatheringAndFarmingAreTheirOwnHands()
	{
		Flow fish = only(delta("Raw shark", 1), xp(Skill.FISHING));
		assertEquals(Source.GATHERED, fish.source);
		assertEquals("Fishing", fish.skill);
		Flow herbs = only(delta("Ranarr weed", 6), xp(Skill.FARMING));
		assertEquals(Source.FARMED, herbs.source);
		assertTrue(herbs.source.isSelf());
		Flow planted = only(delta("Ranarr seed", -1), xp(Skill.FARMING));
		assertEquals(Use.PLANTED, planted.use);
	}

	@Test
	public void aTickWithBothKindsFilesByTheItem()
	{
		// Barbarian fishing gives Fishing and Agility; cooking on the spot would add Cooking.
		List<Flow> flows = Classify.tick(delta("Raw karambwan", 1, "Cooked karambwan", 1), xp(Skill.FISHING, Skill.COOKING), sacks);
		for (Flow f : flows)
		{
			assertEquals(f.store.startsWith("Raw") ? Source.GATHERED : Source.MADE, f.source);
		}
	}

	@Test
	public void pickingUpIsLootAndDroppingIsNoBurn()
	{
		Flow take = only(delta("Ranarr seed", 2), xp(Skill.HITPOINTS).actions(Collections.singletonList(click("Take", "Ranarr seed", "Ranarr seed"))));
		assertEquals(Source.LOOTED, take.source);
		Flow drop = only(delta("Bones", -1), xp().actions(Collections.singletonList(click("Drop", "Bones", "Bones"))));
		assertEquals(Use.DROPPED, drop.use);
		assertTrue(!drop.use.isBurn());
	}

	@Test
	public void runesAndAmmoAreSpentEvenWithoutExperience()
	{
		assertEquals(Use.CAST, only(delta("Law rune", -1), xp()).use);
		assertEquals(Use.FIRED, only(delta("Ruby dragon bolts (e)", -1), xp()).use);
		assertEquals(Use.CAST, only(delta("Blood rune", -2), xp(Skill.MAGIC, Skill.HITPOINTS)).use);
		assertEquals(Use.FIRED, only(delta("Amethyst arrow", -1), xp(Skill.RANGED, Skill.HITPOINTS)).use);
	}

	@Test
	public void enchantingBoltsIsMagicMaking()
	{
		List<Flow> flows = Classify.tick(delta("Ruby dragon bolts", -10, "Ruby dragon bolts (e)", 10, "Cosmic rune", -1, "Blood rune", -1),
			xp(Skill.MAGIC), sacks);
		for (Flow f : flows)
		{
			if (f.isGain())
			{
				assertEquals(Source.MADE, f.source);
				assertEquals("Magic", f.skill);
			}
			else if (Catalogue.family(f.store) == Family.RUNES)
			{
				assertEquals(Use.CAST, f.use);
			}
		}
	}

	@Test
	public void shopsAreBoughtAndSpent()
	{
		List<Flow> flows = Classify.tick(delta("Feather", 100, "Coins", -300), xp().shop(true), sacks);
		for (Flow f : flows)
		{
			if (f.isGain())
			{
				assertEquals(Source.BOUGHT, f.source);
			}
			else
			{
				assertEquals(Use.SPENT, f.use);
				assertTrue(f.use.isBurn());
			}
		}
		Flow sold = only(delta("Coins", 50), xp().shop(true));
		assertEquals(Source.SOLD, sold.source);
		Flow alched = only(delta("Coins", 1200), xp(Skill.MAGIC));
		assertEquals(Source.ALCHED, alched.source);
	}

	@Test
	public void deathAndTradeAreNotThePaceOfPlay()
	{
		assertEquals(Use.DIED, only(delta("Shark", -20), xp().died(true)).use);
		assertEquals(Use.TRADED, only(delta("Shark", -20), xp().trade(true)).use);
		assertEquals(Source.TRADED, only(delta("Shark", 20), xp().trade(true)).source);
	}

	@Test
	public void containersHoldWhatWentInAndPlaceWhatArrivedUnseen()
	{
		// Twenty coal put in a coal bag is a move, not a loss.
		List<Flow> in = Classify.tick(delta("Coal", -20), xp().actions(Collections.singletonList(click("Fill", "Coal bag", null))), sacks);
		assertTrue(in.isEmpty());
		assertEquals(20L, (long) sacks.get("Coal"));

		// Thirty come out: twenty were the player's, ten went in unseen while mining.
		Map<Skill, Long> recent = new HashMap<>();
		recent.put(Skill.MINING, 5000L);
		Flow out = only(delta("Coal", 30), xp().actions(Collections.singletonList(click("Empty", "Coal bag", null))).recent(recent));
		assertEquals(Source.GATHERED, out.source);
		assertEquals(10, out.units);
		assertEquals("Mining", out.skill);
		assertNull(sacks.get("Coal"));
	}

	@Test
	public void packsAreBoughtAndOpenedCratesAreRewards()
	{
		Flow feathers = only(delta("Feather", 100), xp().actions(Collections.singletonList(new Classify.Action("Open", "Feather pack", null, true))));
		assertEquals(Source.BOUGHT, feathers.source);
		Flow crate = only(delta("Pure essence", 40), xp().actions(Collections.singletonList(click("Open", "Supply crate", null))));
		assertEquals(Source.REWARD, crate.source);
		assertEquals(Source.OTHER, only(delta("Coins", 5000), xp()).source);
	}

	@Test
	public void arrivalsFollowRecentWork()
	{
		Map<Skill, Long> recent = new HashMap<>();
		recent.put(Skill.FISHING, 20_000L);
		recent.put(Skill.HITPOINTS, 100L);
		assertEquals(Source.GATHERED, Classify.arrival("Raw shark", 28, recent).source);
		assertEquals(Source.LOOTED, Classify.arrival("Shark", 3, recent).source);
		assertEquals(Source.OTHER, Classify.arrival("Shark", 3, Collections.emptyMap()).source);
	}
}

package com.codex.ironworks.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class FindTest
{
	private static Map<Integer, Long> items(long... pairs)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((int) pairs[i], pairs[i + 1]);
		}
		return m;
	}

	@Test
	public void holdingsAndNamesSurviveASave()
	{
		Works w = new Works(0);
		Map<Integer, String> names = new HashMap<>();
		names.put(4151, "Abyssal whip");
		names.put(385, "Shark");
		w.hold(Spot.BANK, items(4151, 1, 385, 200), names, 10);
		Works back = Works.read(new Gson(), w.write(new Gson()), 20).works;
		assertEquals(200L, (long) back.holding(Spot.BANK).getItems().get(385));
		assertEquals("Abyssal whip", back.itemName(4151));
	}

	@Test
	public void namesOfItemsNoLongerHeldAreDropped()
	{
		Works w = new Works(0);
		w.hold(Spot.INVENTORY, items(385, 5), Collections.singletonMap(385, "Shark"), 1);
		w.hold(Spot.INVENTORY, items(), Collections.emptyMap(), 2);
		Works back = Works.read(new Gson(), w.write(new Gson()), 3).works;
		assertNull(back.itemName(385));
	}

	@Test
	public void deathWaitsAtTheGraveThenDeathsOfficeUntilTakenBack()
	{
		Works w = new Works(0);
		w.played(java.time.LocalDate.of(2026, 10, 1), 60_000);
		w.died(items(4151, 1, 385, 20), Collections.singletonMap(4151, "Abyssal whip"), 330, 100);
		Death d = w.getDeath();
		assertNotNull(d);
		assertEquals(Death.GRAVE_MS, d.graveLeft(w.getPlayed()));
		w.played(java.time.LocalDate.of(2026, 10, 1), Death.GRAVE_MS + 1);
		assertEquals(0, d.graveLeft(w.getPlayed()));
		assertTrue(w.regained(items(4151, 1)));
		assertNotNull(w.getDeath());
		w.regained(items(385, 19));
		assertNull("A tenth left is settled", w.getDeath());
	}

	@Test
	public void ratesCountOnlyTimeAtIt()
	{
		Works w = new Works(0);
		List<Flow> one = Collections.singletonList(Flow.in("Snape grass", 10, Source.GATHERED, "Farming"));
		long t = 1_700_000_000_000L;
		for (int i = 0; i < 40; i++)
		{
			w.rate(one, t);
			t += 15_000;
		}
		t += 3_600_000;
		w.rate(one, t);
		Rate r = w.rate("Snape grass", Source.GATHERED);
		assertEquals(410, r.getUnits());
		assertEquals(39 * 15_000L, r.getMs());
		assertEquals(410 / (39 * 15_000 / 3_600_000.0), r.perHour(), 0.01);
	}

	@Test
	public void everyWayIsForAStore()
	{
		Catalogue.Lookup lookup = Catalogue.standard();
		for (String store : Catalogue.all())
		{
			for (Ways.Way way : Ways.of(store))
			{
				assertTrue(store, way.text.length() > 5 && !way.text.endsWith("."));
			}
		}
		assertTrue(!Ways.of("Snape grass").isEmpty());
		assertTrue("Herbs fall back to their shelf", !Ways.of("Kwuarm").isEmpty());
		assertNotNull(lookup.match("Snape grass"));
	}
}

package com.codex.ironworks.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class PriceTest
{
	/** Coins paid for n bought from a stock of s, at a first price of 5 climbing by 0.1 a unit below 100. */
	private static long[] buy(int stock, int n)
	{
		double coins = 0;
		for (int i = 0; i < n; i++)
		{
			coins += 5 + 0.1 * (100 - (stock - i));
		}
		return new long[]{stock, n, Math.round(coins)};
	}

	@Test
	public void learnsTheFirstPriceAndTheClimb()
	{
		List<long[]> p = new ArrayList<>();
		p.add(buy(100, 10));
		p.add(buy(90, 30));
		p.add(buy(100, 50));
		Price price = Price.fit(p, 100);
		assertEquals(5, price.first, 0.1);
		assertEquals(0.1, price.climb, 0.01);
		// The price is a tenth up after five more, so a sixth is the last one bought on a world.
		assertEquals(6, price.perWorld(0.1));
		assertEquals(Math.round(5 * 100 + 0.1 * 100 * 99 / 2.0), price.cost(100), 10);
		assertEquals(16 * price.cost(6) + price.cost(4), price.costHopping(100, 0.1), 20.0);
	}

	@Test
	public void oneFlatPurchaseIsAnAverage()
	{
		List<long[]> p = new ArrayList<>();
		p.add(new long[]{1000, 100, 300});
		Price price = Price.fit(p, 1000);
		assertEquals(3, price.first, 0.001);
		assertEquals(0, price.climb, 0.001);
		assertEquals(1000, price.perWorld(0.1));
	}

	@Test
	public void noPurchasesNoPrice()
	{
		assertNull(Price.fit(new ArrayList<>(), 10));
	}

	@Test
	public void purchasesAtAShopTeachTheWare()
	{
		Works w = new Works(0);
		Shop s = w.visit("Feather shop", 1, 301, 0);
		w.stock(s, 314, "Feather", 301, 990, 1);
		w.stock(s, 314, "Feather", 301, 1000, 0);
		w.stock(s, 314, "Feather", 301, 900, 2);
		java.util.Map<String, Long> paid = new java.util.HashMap<>();
		paid.put("Coins", 300L);
		w.purchase(s, 314, "Feather", 100, paid, 301, 2);
		Price price = s.getWares().get(0).price();
		assertEquals(3, price.first, 0.001);
	}
}

package com.codex.ironworks.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.time.LocalDate;
import java.util.Collections;
import org.junit.Test;

public class RunwayTest
{
	private static final LocalDate TODAY = LocalDate.of(2026, 10, 20);

	private static Works played(long hours, String store, long used, long gained)
	{
		Works w = new Works(0);
		w.played(TODAY, hours * 3_600_000L);
		if (used > 0)
		{
			w.record(Collections.singletonList(Flow.out(store, used, Use.CONSUMED, null)), TODAY);
		}
		if (gained > 0)
		{
			w.record(Collections.singletonList(Flow.in(store, gained, Source.FARMED, "Farming")), TODAY);
		}
		return w;
	}

	@Test
	public void lastsAsManyHoursAsTheStockAtTheBurn()
	{
		Works w = played(4, "Prayer potion", 80, 0);
		Runway r = Runway.of("Prayer potion", 100, w.window(TODAY, 7), 10, 2);
		assertEquals(20, r.burn, 1e-9);
		assertEquals(5, r.hours, 1e-9);
		assertEquals(Runway.Status.SHORT, r.status);
		assertEquals(100, r.need);
		assertTrue(r.wanting());
	}

	@Test
	public void lowOutAndSteady()
	{
		Works w = played(4, "Shark", 400, 0);
		assertEquals(Runway.Status.LOW, Runway.of("Shark", 50, w.window(TODAY, 7), 10, 2).status);
		assertEquals(Runway.Status.OUT, Runway.of("Shark", 0, w.window(TODAY, 7), 10, 2).status);
		Works farm = played(4, "Ranarr weed", 40, 60);
		assertEquals(Runway.Status.STEADY, Runway.of("Ranarr weed", 10, farm.window(TODAY, 7), 10, 2).status);
	}

	@Test
	public void needsAnHourOfPlayAndUseToTell()
	{
		Works shortPlay = played(0, "Shark", 10, 0);
		shortPlay.played(TODAY, 30 * 60_000L);
		assertEquals(Runway.Status.LEARNING, Runway.of("Shark", 10, shortPlay.window(TODAY, 7), 10, 2).status);
		Works unused = played(3, "Shark", 0, 0);
		Runway idle = Runway.of("Shark", 10, unused.window(TODAY, 7), 10, 2);
		assertEquals(Runway.Status.IDLE, idle.status);
		assertTrue(Double.isInfinite(idle.hours));
	}

	@Test
	public void sellingAndDyingDoNotSetThePace()
	{
		Works w = played(4, "Shark", 0, 0);
		w.record(Collections.singletonList(Flow.out("Shark", 500, Use.DIED, null)), TODAY);
		w.record(Collections.singletonList(Flow.out("Shark", 500, Use.SOLD, null)), TODAY);
		assertEquals(Runway.Status.IDLE, Runway.of("Shark", 10, w.window(TODAY, 7), 10, 2).status);
	}

	@Test
	public void theWindowCountsOnlyItsDays()
	{
		Works w = played(2, "Shark", 10, 0);
		w.played(TODAY.minusDays(10), 5 * 3_600_000L);
		w.record(Collections.singletonList(Flow.out("Shark", 1000, Use.CONSUMED, null)), TODAY.minusDays(10));
		Window week = w.window(TODAY, 7);
		assertEquals(2 * 3_600_000L, week.getPlayed());
		assertEquals(10, week.tally("Shark").burned());
		Window all = w.window(TODAY, 0);
		assertEquals(7 * 3_600_000L, all.getPlayed());
		assertEquals(1010, all.tally("Shark").burned());
	}
}

package com.codex.ironworks.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.time.LocalDate;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class SavesTest
{
	private static final LocalDate TODAY = LocalDate.of(2026, 10, 20);
	private final Gson gson = new Gson();

	private Works sample()
	{
		Works w = new Works(1);
		w.setAccount(3);
		Map<String, Long> bank = new HashMap<>();
		bank.put("Shark", 400L);
		bank.put("Prayer potion", 120L);
		w.place(Place.BANK, bank, 5);
		w.place(Place.CARRIED, Collections.singletonMap("Shark", 20L), 5);
		w.icon("Shark", 385, true);
		w.played(TODAY, 3_600_000L);
		w.record(Collections.singletonList(Flow.out("Shark", 12, Use.CONSUMED, null)), TODAY);
		w.record(Collections.singletonList(Flow.in("Prayer potion", 30, Source.MADE, "Herblore")), TODAY);
		Shop s = w.visit("Gerrant's Fishy Business", 12082, 302, 10);
		w.stock(s, 11881, "Feather pack", 302, 7, 10);
		w.purchase(s, 11881, "Feather pack", 3, Collections.singletonMap("Coins", 6000L), 301, 11);
		w.pack("Feather pack", 100);
		w.getSacks().put("Coal", 27L);
		return w;
	}

	@Test
	public void aSaveReadsBackWhole()
	{
		String json = sample().write(gson);
		Works.Loaded back = Works.read(gson, json, 99);
		assertFalse(back.damaged);
		Works w = back.works;
		assertEquals(3, w.getAccount());
		assertEquals(420, w.stock("Shark"));
		assertEquals(385, w.icon("Shark"));
		assertEquals(12, w.window(TODAY, 7).tally("Shark").burned());
		assertEquals(30, w.window(TODAY, 0).tally("Prayer potion").self());
		assertEquals(3, w.getShops().get(0).getWare(11881).getBought());
		assertEquals(1, w.getRuns().size());
		assertEquals(27L, (long) w.getSacks().get("Coal"));
		assertEquals(json, w.write(gson));
	}

	@Test
	public void nothingSavedStartsFresh()
	{
		Works.Loaded fresh = Works.read(gson, null, 7);
		assertFalse(fresh.damaged);
		assertEquals(-1, fresh.works.getAccount());
		assertEquals(7, fresh.works.getSince());
	}

	@Test
	public void aSaveCutShortKeepsWhatCameBeforeTheCut()
	{
		String json = sample().write(gson);
		String cut = json.substring(0, json.indexOf("\"days\""));
		Works.Loaded back = Works.read(gson, cut, 99);
		assertTrue(back.damaged);
		assertEquals(420, back.works.stock("Shark"));
		assertEquals(3, back.works.getAccount());
	}

	@Test
	public void impossibleFiguresAreSetRight()
	{
		String json = "{\"account\":2,\"played\":-5,\"places\":{\"BANK\":{\"Shark\":-4,\"Lobster\":10}},"
			+ "\"days\":{\"not a day\":{\"played\":4},\"2026-10-20\":{\"played\":-1,\"stores\":{\"Shark\":{\"in\":{\"LOOTED\":-3}}}}},"
			+ "\"shops\":[null,{\"name\":\"\",\"wares\":{\"1\":{\"base\":-2,\"restockMs\":-9}}}],\"runs\":[null]}";
		Works.Loaded back = Works.read(gson, json, 99);
		Works w = back.works;
		assertEquals(0, w.getPlayed());
		assertEquals(0, w.stock("Shark"));
		assertEquals(10, w.stock("Lobster"));
		assertEquals(0, w.window(TODAY, 1).getPlayed());
		assertEquals(1, w.getShops().size());
		assertEquals("Shop", w.getShops().get(0).getName());
		assertEquals(0, w.getShops().get(0).getWare(1).getBase());
		assertEquals(0, w.getRuns().size());
	}

	@Test
	public void aFieldFromALaterVersionIsKeptAside()
	{
		String json = sample().write(gson);
		String later = "{\"newThing\":{\"a\":1}," + json.substring(1);
		assertTrue(Works.read(gson, later, 99).damaged);
	}

	@Test
	public void oldDaysFallAwayButTotalsStay()
	{
		Works w = sample();
		w.played(TODAY.minusDays(60), 1000);
		w.record(Collections.singletonList(Flow.out("Shark", 5, Use.CONSUMED, null)), TODAY.minusDays(60));
		w.trim(TODAY);
		assertEquals(0, w.window(TODAY, 90).tally("Shark").burned() - 12);
		assertEquals(17, w.window(TODAY, 0).tally("Shark").burned());
	}
}

package com.codex.ironworks.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import org.junit.Test;

public class ShopsTest
{
	private static final long MIN = 60_000L;

	@Test
	public void restockPaceIsLearnedFromStockClimbing()
	{
		Works w = new Works(0);
		Shop shop = w.visit("Gerrant's Fishy Business", 12082, 302, 0);
		w.stock(shop, 11881, "Feather pack", 302, 10, 0);
		w.stock(shop, 11881, "Feather pack", 302, 0, 5_000);
		w.purchase(shop, 11881, "Feather pack", 10, Collections.singletonMap("Coins", 20_000L), 301, 5_000);
		// Five back a minute later, still short of ten: one every twelve seconds.
		w.stock(shop, 11881, "Feather pack", 302, 5, 5_000 + MIN);
		Ware ware = shop.getWare(11881);
		assertEquals(10, ware.getBase());
		assertEquals(12_000, ware.getRestockMs(), 1);
		assertEquals(10, ware.getBought());
		assertEquals(20_000L, (long) ware.getSpent().get("Coins"));
		assertEquals(5_000 + MIN + 60_000, ware.fullAt(302));
		assertEquals(10, ware.expected(302, 5_000 + 3 * MIN));
		assertEquals(-1, ware.expected(303, 0));
		assertEquals(120_000, ware.refillMs());
	}

	@Test
	public void aFullShopOnlyBoundsThePace()
	{
		Works w = new Works(0);
		Shop shop = w.visit("Ordan", 7757, 330, 0);
		w.stock(shop, 453, "Coal", 330, 100, 0);
		w.stock(shop, 453, "Coal", 330, 20, 1_000);
		w.stock(shop, 453, "Coal", 330, 100, 1_000 + 8 * MIN);
		// Eighty back in eight minutes at most, so no slower than six seconds each.
		assertEquals(6_000, shop.getWare(453).getRestockMs(), 1);
	}

	@Test
	public void visitsCloseTogetherAreOneRun()
	{
		Works w = new Works(0);
		Shop a = w.visit("Gerrant's Fishy Business", 12082, 302, 0);
		w.purchase(a, 11881, "Feather pack", 10, Collections.singletonMap("Coins", 20_000L), 301, 1_000);
		w.visit("Gerrant's Fishy Business", 12082, 303, 2 * MIN);
		w.visit("Betty's Magic Emporium", 12082, 303, 4 * MIN);
		w.visit("Gerrant's Fishy Business", 12082, 304, 30 * MIN);
		assertEquals(2, w.getRuns().size());
		Run first = w.getRuns().get(0);
		assertEquals(2, first.getShops().size());
		assertEquals(2, first.worlds());
		assertEquals(3, first.getVisits());
		assertEquals(10, first.items());
		assertEquals(4 * MIN, first.duration());
		assertEquals(3, a.getVisits());
		assertTrue(w.shop(a.key()) == a);
	}

	@Test
	public void namesakesInDifferentPlacesAreDifferentShops()
	{
		Works w = new Works(0);
		w.visit("General Store", 12850, 301, 0);
		w.visit("General Store", 12853, 301, MIN);
		assertEquals(2, w.getShops().size());
	}
}

package com.codex.ironworks.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.time.LocalDate;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;

public class TrackerTest
{
	private static final LocalDate DAY = LocalDate.of(2026, 10, 20);

	private Works works;
	private Tracker tracker;
	private long time;

	@Before
	public void setUp()
	{
		works = new Works(0);
		tracker = new Tracker(works);
	}

	private static Map<String, Long> units(Object... pairs)
	{
		Map<String, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((String) pairs[i], ((Number) pairs[i + 1]).longValue());
		}
		return m;
	}

	private List<Flow> tick(Map<String, Long> carried, Classify.Context ctx)
	{
		return tracker.tick(carried, ctx, DAY, time += 600);
	}

	private List<Flow> tick(Map<String, Long> carried)
	{
		return tick(carried, new Classify.Context().xp(EnumSet.noneOf(Skill.class)));
	}

	private static Classify.Context click(String option, String target, String store)
	{
		return new Classify.Context().xp(EnumSet.noneOf(Skill.class))
			.actions(Collections.singletonList(new Classify.Action(option, target, store, false)));
	}

	/** Opens the bank, lets it settle, and returns what settling recorded. */
	private List<Flow> openBank(Map<String, Long> bank, Map<String, Long> carried, Classify.Context ctx)
	{
		tracker.bankOpened();
		works.place(Place.BANK, bank, time);
		List<Flow> all = new java.util.ArrayList<>();
		for (int i = 0; i < Tracker.OPEN_TICKS; i++)
		{
			all.addAll(tick(carried, ctx));
		}
		return all;
	}

	private List<Flow> closeBank(Map<String, Long> carried, Classify.Context ctx)
	{
		tracker.bankClosed();
		List<Flow> all = new java.util.ArrayList<>();
		for (int i = 0; i < Tracker.CLOSE_TICKS; i++)
		{
			all.addAll(tick(carried, ctx));
		}
		return all;
	}

	@Test
	public void theFirstReadingIsNotAGain()
	{
		assertTrue(tick(units("Shark", 20)).isEmpty());
		assertEquals(20, works.stock("Shark"));
		List<Flow> eaten = tick(units("Shark", 19), click("Eat", "Shark", "Shark"));
		assertEquals(1, eaten.size());
		assertEquals(Use.CONSUMED, eaten.get(0).use);
		assertEquals(1, works.window(DAY, 1).tally("Shark").burned());
	}

	@Test
	public void bankingIsAMoveNotAGainOrLoss()
	{
		tick(units("Shark", 0));
		openBank(units("Shark", 100), units(), new Classify.Context());
		works.place(Place.BANK, units("Shark", 72), time);
		tick(units("Shark", 28));
		assertTrue(closeBank(units("Shark", 28), new Classify.Context()).isEmpty());
		assertEquals(100, works.stock("Shark"));
		assertTrue(works.window(DAY, 0).getStores().isEmpty());
	}

	@Test
	public void aHerbSackEmptiedAtTheBankIsFarmedHerbs()
	{
		Map<Skill, Long> recent = new HashMap<>();
		recent.put(Skill.FARMING, 3_000L);
		Classify.Context ctx = new Classify.Context().recent(recent);
		tick(units());
		openBank(units("Ranarr weed", 10), units(), ctx);
		works.place(Place.BANK, units("Ranarr weed", 40), time);
		tick(units(), ctx);
		List<Flow> flows = closeBank(units(), ctx);
		assertEquals(1, flows.size());
		assertEquals(Source.FARMED, flows.get(0).source);
		assertEquals(30, flows.get(0).units);
	}

	@Test
	public void whatTheBankGainedUnseenSinceTheLastVisitIsCounted()
	{
		Map<Skill, Long> recent = new HashMap<>();
		recent.put(Skill.FISHING, 9_000L);
		Classify.Context ctx = new Classify.Context().recent(recent);
		tick(units());
		openBank(units("Raw shark", 10), units(), ctx);
		closeBank(units(), ctx);
		// Away from the bank, a full barrel is sent to it: the next visit finds 28 more.
		tick(units(), ctx);
		List<Flow> flows = openBank(units("Raw shark", 38), units(), ctx);
		assertEquals(1, flows.size());
		assertEquals(Source.GATHERED, flows.get(0).source);
		assertEquals(28, flows.get(0).units);
	}

	@Test
	public void aDepositBoxMovesToTheBank()
	{
		tick(units());
		openBank(units("Coal", 0), units(), new Classify.Context());
		closeBank(units(), new Classify.Context());
		tick(units("Coal", 27), new Classify.Context().xp(EnumSet.of(Skill.MINING)));
		tracker.storageOpened(true);
		tick(units());
		tracker.storageClosed();
		tick(units());
		tick(units());
		assertTrue(openBank(units("Coal", 27), units(), new Classify.Context()).isEmpty());
		assertEquals(27, works.window(DAY, 0).tally("Coal").in(Source.GATHERED));
		assertEquals(0, works.window(DAY, 0).tally("Coal").burned());
	}

	@Test
	public void afterALoginTheBankIsNotComparedWithHowItWasLeft()
	{
		tick(units());
		openBank(units("Shark", 10), units(), new Classify.Context());
		closeBank(units(), new Classify.Context());
		tracker.restart(DAY);
		tick(units());
		// Played on another client in between: the bank is simply taken as it is.
		assertTrue(openBank(units("Shark", 500), units(), new Classify.Context()).isEmpty());
	}

	@Test
	public void aStaminaDrunkAtTheBankIsConsumed()
	{
		tick(units());
		openBank(units("Stamina potion", 40), units(), new Classify.Context());
		works.place(Place.BANK, units("Stamina potion", 36), time);
		tick(units("Stamina potion", 4));
		tick(units("Stamina potion", 3));
		List<Flow> flows = closeBank(units("Stamina potion", 3), new Classify.Context());
		assertEquals(1, flows.size());
		assertEquals(Use.CONSUMED, flows.get(0).use);
		assertEquals(1, flows.get(0).units);
	}

	@Test
	public void deathHoldsItemsInAGraveUntilTakenBack()
	{
		tick(units("Shark", 10));
		assertTrue(tick(units(), new Classify.Context().died(true)).isEmpty());
		assertTrue(tick(units("Shark", 10), click("Take", "Shark", "Shark")).isEmpty());
		assertEquals(0, works.window(DAY, 0).tally("Shark").burned());

		tick(units("Shark", 10), new Classify.Context().died(true));
		tick(units(), new Classify.Context().died(true));
		for (int i = 0; i < Tracker.GRAVE_TICKS; i++)
		{
			tick(units());
		}
		assertEquals(10, works.window(DAY, 0).tally("Shark").out(Use.DIED));
	}

	@Test
	public void hoppingStartsTheReadingAfresh()
	{
		tick(units("Shark", 10));
		tracker.hop();
		assertTrue(tick(units("Shark", 12)).isEmpty());
	}
}

package com.codex.ironworks.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

public class WorkshopTest
{
	private static final Catalogue.Lookup LOOKUP = Catalogue.standard();

	private static Map<String, Long> stocks(Object... pairs)
	{
		Map<String, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((String) pairs[i], ((Number) pairs[i + 1]).longValue());
		}
		return m;
	}

	@Test
	public void everyRecipeIsMadeOfStoresAndMakesWhatItSays()
	{
		for (Recipe r : Recipes.all())
		{
			assertTrue(r.product, r.productItem > 0);
			assertTrue(r.product, r.level >= 1 && r.level <= 99);
			assertTrue(r.product, r.xp >= 0);
			for (String in : r.inputs.keySet())
			{
				Catalogue.Match m = LOOKUP.match(in);
				assertNotNull(r.product + " needs " + in + ", which is no store", m);
				assertEquals(in, m.store);
			}
			if (r.count > 0 && r.tier < 9)
			{
				// Intermediate things must be stores, or nothing could be made from them.
				boolean usedLater = false;
				for (Recipe o : Recipes.all())
				{
					usedLater |= o.tier > r.tier && LOOKUP.match(r.product) != null && o.inputs.containsKey(LOOKUP.match(r.product).store);
				}
				if (r.xp == 0)
				{
					assertTrue(r.product + " gives nothing and feeds nothing", usedLater);
				}
			}
		}
	}

	@Test
	public void herbsAndSecondariesBecomePotionsCountedInDoses()
	{
		Workshop w = Workshop.plan(stocks("Ranarr weed", 100, "Vial of water", 100, "Snape grass", 60), LOOKUP,
			Collections.emptyMap(), Altar.GILDED);
		Workshop.Plan herblore = w.plan(Skill.HERBLORE);
		assertNotNull(herblore);
		assertEquals(60 * 87.5, herblore.xp, 0.01);
		Workshop.Short s = herblore.shorts.get(0);
		assertEquals("Snape grass", s.input);
		assertEquals(40, s.need);
		assertEquals(40, s.more);
	}

	@Test
	public void unfinishedPotionsShortOfVialsSayWhatTheyWouldFinish()
	{
		Workshop w = Workshop.plan(stocks("Ranarr weed", 50, "Vial of water", 20, "Snape grass", 50), LOOKUP,
			Collections.emptyMap(), Altar.GILDED);
		Workshop.Plan herblore = w.plan(Skill.HERBLORE);
		assertEquals(20 * 87.5, herblore.xp, 0.01);
		boolean vials = false;
		for (Workshop.Short s : herblore.shorts)
		{
			if (s.input.equals("Vial of water"))
			{
				vials = true;
				assertEquals(30, s.need);
				assertEquals(30 * 87.5, s.xp, 0.01);
			}
		}
		assertTrue(vials);
	}

	@Test
	public void bonesCountAtTheChosenAltarAndAshesDoNot()
	{
		Map<String, Long> st = stocks("Dragon bones", 10, "Infernal ashes", 10);
		Workshop bury = Workshop.plan(st, LOOKUP, Collections.emptyMap(), Altar.BURY);
		Workshop gilded = Workshop.plan(st, LOOKUP, Collections.emptyMap(), Altar.GILDED);
		assertEquals(10 * 72 + 10 * 110, bury.plan(Skill.PRAYER).xp, 0.01);
		assertEquals(10 * 72 * 3.5 + 10 * 110, gilded.plan(Skill.PRAYER).xp, 0.01);
	}

	@Test
	public void logsAreFletchedBeforeAnyAreBurned()
	{
		Workshop w = Workshop.plan(stocks("Yew logs", 100, "Bow string", 40), LOOKUP, Collections.emptyMap(), Altar.GILDED);
		assertEquals(40 * 150 + 60 * 75, w.plan(Skill.FLETCHING).xp, 0.01);
		assertNull(w.plan(Skill.FIREMAKING));
	}

	@Test
	public void recipesAboveTheLevelAreKeptApart()
	{
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.COOKING, 70);
		Workshop w = Workshop.plan(stocks("Raw shark", 10, "Raw lobster", 10), LOOKUP, levels, Altar.GILDED);
		Workshop.Plan cooking = w.plan(Skill.COOKING);
		assertEquals(10 * 120, cooking.xp, 0.01);
		assertEquals(10 * 210, cooking.lockedXp, 0.01);
		assertEquals(10 * 120, w.total(), 0.01);
		assertEquals(10 * 210, w.lockedTotal(), 0.01);
	}

	@Test
	public void chainsRunThroughSeveralSteps()
	{
		// Sand and soda ash become glass, glass an orb, the orb is charged, and a staff takes it.
		Workshop w = Workshop.plan(stocks("Bucket of sand", 5, "Soda ash", 5, "Cosmic rune", 15, "Air rune", 150, "Battlestaff", 5),
			LOOKUP, Collections.emptyMap(), Altar.GILDED);
		assertEquals(5 * 20 + 5 * 52.5 + 5 * 137.5, w.plan(Skill.CRAFTING).xp, 0.01);
		assertEquals(5 * 76, w.plan(Skill.MAGIC).xp, 0.01);
	}

	@Test
	public void nothingToMakeIsEmpty()
	{
		Workshop w = Workshop.plan(stocks("Coins", 1000), LOOKUP, Collections.emptyMap(), Altar.GILDED);
		assertTrue(w.plans().isEmpty());
		assertFalse(w.total() > 0);
	}
}

package com.codex.ironworks.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import org.junit.Test;

public class FormatTest
{
	@Test
	public void amountsFollowTheSuiteRule()
	{
		// In full below 10,000; whole k below a million; M to one decimal; B to two.
		assertEquals("8,240", Format.amount(8_240));
		assertEquals("10k", Format.amount(10_000));
		assertEquals("41k", Format.amount(41_200));
		assertEquals("96k", Format.amount(95_700));
		assertEquals("412k", Format.amount(412_000));
		assertEquals("1.2M", Format.amount(1_240_000));
		assertEquals("26.0M", Format.amount(26_000_000));
		assertEquals("812.4M", Format.amount(812_400_000));
		assertEquals("2.10B", Format.amount(2_100_000_000L));
		// Rounding that reaches the next unit is written in it.
		assertEquals("100k", Format.amount(99_960));
		assertEquals("1.0M", Format.amount(999_600));
		assertEquals("999k", Format.amount(999_499));
		assertEquals("1.00B", Format.amount(999_960_000));
		assertEquals("-45k", Format.coins(-45_200));
		assertEquals("+1,240", Format.count(1_240));
	}

	@Test
	public void aShortfallNeverReadsAsMet()
	{
		// 10,450 of 10,499 would read "10k / 10k"; while short, the two figures always differ.
		String[] pair = Format.pair(10_450, 10_499);
		assertNotEquals(pair[0], pair[1]);
		assertEquals("10,450", pair[0]);
		assertEquals("10,499", pair[1]);
		String[] met = Format.pair(10_499, 10_499);
		assertEquals("10k", met[0]);
		assertEquals("10k", met[1]);
		assertEquals("12k", Format.pair(12_000, 40_000)[0]);
		// A share just short of whole is never rounded up to it.
		assertEquals("99%", Format.percent(0.996));
		assertEquals("100%", Format.percent(1));
		assertEquals("<1%", Format.percent(0.004));
	}
}

